    CreateEndpointMessage.add_member(:endpoint_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EndpointIdentifier', traits: {"smithy.api#documentation" => "<p>The database endpoint identifier. Identifiers must begin with a letter and must contain\n         only ASCII letters, digits, and hyphens. They can't end with a hyphen, or contain two\n         consecutive hyphens.</p>", "smithy.api#required" => {}}))
    CreateEndpointMessage.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ReplicationEndpointTypeValue, location_name: 'EndpointType', traits: {"smithy.api#documentation" => "<p>The type of endpoint. Valid values are <code>source</code> and\n         <code>target</code>.</p>", "smithy.api#required" => {}}))
    CreateEndpointMessage.add_member(:engine_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineName', traits: {"smithy.api#documentation" => "<p>The type of engine for the endpoint. Valid values, depending on the\n            <code>EndpointType</code> value, include <code>\"mysql\"</code>, <code>\"oracle\"</code>,\n            <code>\"postgres\"</code>, <code>\"mariadb\"</code>, <code>\"aurora\"</code>,\n            <code>\"aurora-postgresql\"</code>, <code>\"opensearch\"</code>, <code>\"redshift\"</code>,\n            <code>\"s3\"</code>, <code>\"db2\"</code>, <code>\"db2-zos\"</code>, <code>\"azuredb\"</code>,\n            <code>\"sybase\"</code>, <code>\"dynamodb\"</code>, <code>\"mongodb\"</code>,\n            <code>\"kinesis\"</code>, <code>\"kafka\"</code>, <code>\"elasticsearch\"</code>,\n            <code>\"docdb\"</code>, <code>\"sqlserver\"</code>, <code>\"neptune\"</code>,\n            <code>\"babelfish\"</code>, <code>redshift-serverless</code>,\n            <code>aurora-serverless</code>, <code>aurora-postgresql-serverless</code>,\n            <code>gcp-mysql</code>, <code>azure-sql-managed-instance</code>, <code>redis</code>,\n            <code>dms-transfer</code>.</p>", "smithy.api#required" => {}}))
    CreateEndpointMessage.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>The user name to be used to log in to the endpoint database.</p>"}))
    CreateEndpointMessage.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>The password to be used to log in to the endpoint database.</p>"}))
    CreateEndpointMessage.add_member(:server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerName', traits: {"smithy.api#documentation" => "<p>The name of the server where the endpoint database resides.</p>"}))
    CreateEndpointMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port used by the endpoint database.</p>"}))
    CreateEndpointMessage.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The name of the endpoint database. For a MySQL source or target endpoint, do not specify\n         DatabaseName. To migrate to a specific database, use this setting and\n            <code>targetDbType</code>.</p>"}))
    CreateEndpointMessage.add_member(:extra_connection_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ExtraConnectionAttributes', traits: {"smithy.api#documentation" => "<p>Additional attributes associated with the connection. Each attribute is specified as a\n         name-value pair associated by an equal sign (=). Multiple attributes are separated by a\n         semicolon (;) with no additional white space. For information on the attributes available\n         for connecting your source or target endpoint, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Endpoints.html\">Working with DMS Endpoints</a> in\n         the <i>Database Migration Service User Guide.</i>\n         </p>"}))
    CreateEndpointMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>An KMS key identifier that is used to encrypt the connection parameters for the\n         endpoint.</p>\n         <p>If you don't specify a value for the <code>KmsKeyId</code> parameter, then DMS uses\n         your default encryption key.</p>\n         <p>KMS creates the default encryption key for your Amazon Web Services account. Your Amazon Web Services account has\n         a different default encryption key for each Amazon Web Services Region.</p>"}))
    CreateEndpointMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>One or more tags to be assigned to the endpoint.</p>"}))
    CreateEndpointMessage.add_member(:certificate_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CertificateArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the certificate.</p>"}))
    CreateEndpointMessage.add_member(:ssl_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DmsSslModeValue, location_name: 'SslMode', traits: {"smithy.api#documentation" => "<p>The Secure Sockets Layer (SSL) mode to use for the SSL connection. The default is\n            <code>none</code>\n         </p>"}))
    CreateEndpointMessage.add_member(:service_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServiceAccessRoleArn', traits: {"smithy.api#documentation" => "<p> The Amazon Resource Name (ARN) for the service access role that you want to use to\n         create the endpoint. The role must allow the <code>iam:PassRole</code> action.</p>"}))
    CreateEndpointMessage.add_member(:external_table_definition, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ExternalTableDefinition', traits: {"smithy.api#documentation" => "<p>The external table definition. </p>"}))
    CreateEndpointMessage.add_member(:dynamo_db_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: DynamoDbSettings, location_name: 'DynamoDbSettings', traits: {"smithy.api#documentation" => "<p>Settings in JSON format for the target Amazon DynamoDB endpoint. For information about\n         other available settings, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.DynamoDB.html#CHAP_Target.DynamoDB.ObjectMapping\">Using Object Mapping to Migrate Data to DynamoDB</a> in the <i>Database Migration Service\n            User Guide.</i>\n         </p>"}))
    CreateEndpointMessage.add_member(:s3_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Settings, location_name: 'S3Settings', traits: {"smithy.api#documentation" => "<p>Settings in JSON format for the target Amazon S3 endpoint. For more information about\n         the available settings, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.S3.html#CHAP_Target.S3.Configuring\">Extra\n            Connection Attributes When Using Amazon S3 as a Target for DMS</a> in the\n            <i>Database Migration Service User Guide.</i>\n         </p>"}))
    CreateEndpointMessage.add_member(:dms_transfer_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: DmsTransferSettings, location_name: 'DmsTransferSettings', traits: {"smithy.api#documentation" => "<p>The settings in JSON format for the DMS transfer type of source endpoint. </p>\n         <p>Possible settings include the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ServiceAccessRoleArn</code> - The Amazon Resource Name (ARN) used by the\n               service access IAM role. The role must allow the <code>iam:PassRole</code>\n               action.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BucketName</code> - The name of the S3 bucket to use.</p>\n            </li>\n         </ul>\n         <p>Shorthand syntax for these settings is as follows:\n            <code>ServiceAccessRoleArn=string,BucketName=string</code>\n         </p>\n         <p>JSON syntax for these settings is as follows: <code>{ \"ServiceAccessRoleArn\": \"string\",\n            \"BucketName\": \"string\", } </code>\n         </p>"}))
    CreateEndpointMessage.add_member(:mongo_db_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: MongoDbSettings, location_name: 'MongoDbSettings', traits: {"smithy.api#documentation" => "<p>Settings in JSON format for the source MongoDB endpoint. For more information about the\n         available settings, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.MongoDB.html#CHAP_Source.MongoDB.Configuration\">Endpoint configuration settings when using MongoDB as a source for Database Migration Service</a> in\n         the <i>Database Migration Service User Guide.</i>\n         </p>"}))
    CreateEndpointMessage.add_member(:kinesis_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: KinesisSettings, location_name: 'KinesisSettings', traits: {"smithy.api#documentation" => "<p>Settings in JSON format for the target endpoint for Amazon Kinesis Data Streams. For\n         more information about the available settings, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.Kinesis.html#CHAP_Target.Kinesis.ObjectMapping\">Using object mapping to migrate data to a Kinesis data stream</a> in the\n            <i>Database Migration Service User Guide.</i>\n         </p>"}))
    CreateEndpointMessage.add_member(:kafka_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: KafkaSettings, location_name: 'KafkaSettings', traits: {"smithy.api#documentation" => "<p>Settings in JSON format for the target Apache Kafka endpoint. For more information about\n         the available settings, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.Kafka.html#CHAP_Target.Kafka.ObjectMapping\">Using\n            object mapping to migrate data to a Kafka topic</a> in the <i>Database Migration Service User\n            Guide.</i>\n         </p>"}))
    CreateEndpointMessage.add_member(:elasticsearch_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticsearchSettings, location_name: 'ElasticsearchSettings', traits: {"smithy.api#documentation" => "<p>Settings in JSON format for the target OpenSearch endpoint. For more\n         information about the available settings, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.Elasticsearch.html#CHAP_Target.Elasticsearch.Configuration\">Extra Connection Attributes When Using OpenSearch as a Target for\n            DMS</a> in the <i>Database Migration Service User Guide</i>.</p>"}))
    CreateEndpointMessage.add_member(:neptune_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: NeptuneSettings, location_name: 'NeptuneSettings', traits: {"smithy.api#documentation" => "<p>Settings in JSON format for the target Amazon Neptune endpoint. For more information\n         about the available settings, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.Neptune.html#CHAP_Target.Neptune.EndpointSettings\">Specifying graph-mapping rules using Gremlin and R2RML for Amazon\n            Neptune as a target</a> in the <i>Database Migration Service User Guide.</i>\n         </p>"}))
    CreateEndpointMessage.add_member(:redshift_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: RedshiftSettings, location_name: 'RedshiftSettings'))
    CreateEndpointMessage.add_member(:postgre_sql_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: PostgreSQLSettings, location_name: 'PostgreSQLSettings', traits: {"smithy.api#documentation" => "<p>Settings in JSON format for the source and target PostgreSQL endpoint. For information\n         about other available settings, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.PostgreSQL.html#CHAP_Source.PostgreSQL.ConnectionAttrib\">Extra connection attributes when using PostgreSQL as a source for DMS</a> and\n            <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.PostgreSQL.html#CHAP_Target.PostgreSQL.ConnectionAttrib\"> Extra connection attributes when using PostgreSQL as a target for DMS</a> in the\n            <i>Database Migration Service User Guide.</i>\n         </p>"}))
