    DocDbSettings.add_member(:replicate_shard_collections, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ReplicateShardCollections', traits: {"smithy.api#documentation" => "<p>If <code>true</code>, DMS replicates data to shard collections. DMS only uses this\n         setting if the target endpoint is a DocumentDB elastic cluster.</p>\n         <p>When this setting is <code>true</code>, note the following:</p>\n         <ul>\n            <li>\n               <p>You must set <code>TargetTablePrepMode</code> to <code>nothing</code>.</p>\n            </li>\n            <li>\n               <p>DMS automatically sets <code>useUpdateLookup</code> to\n               <code>false</code>.</p>\n            </li>\n         </ul>"}))
