    GcpMySQLSettings.add_member(:after_connect_script, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AfterConnectScript', traits: {"smithy.api#documentation" => "<p>Specifies a script to run immediately after DMS connects to the endpoint.\n         The migration task continues running regardless if the SQL statement succeeds or\n         fails.</p>\n         <p>For this parameter, provide the code of the script itself, not the name of a file\n         containing the script. </p>"}))
    GcpMySQLSettings.add_member(:clean_source_metadata_on_mismatch, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CleanSourceMetadataOnMismatch', traits: {"smithy.api#documentation" => "<p>Cleans and recreates table metadata information on the replication instance when a\n         mismatch occurs. For example, in a situation where running an alter DDL on the table could\n         result in different information about the table cached in the replication instance. </p>"}))
    GcpMySQLSettings.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>Database name for the endpoint. For a MySQL source or target endpoint, don't explicitly\n         specify the database using the <code>DatabaseName</code> request parameter on either the\n            <code>CreateEndpoint</code> or <code>ModifyEndpoint</code> API call. Specifying\n            <code>DatabaseName</code> when you create or modify a MySQL endpoint replicates all the\n         task tables to this single database. For MySQL endpoints, you specify the database only\n         when you specify the schema in the table-mapping rules of the DMS task.\n      </p>"}))
    GcpMySQLSettings.add_member(:events_poll_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'EventsPollInterval', traits: {"smithy.api#documentation" => "<p>Specifies how often to check the binary log for new changes/events when the database is\n         idle. The default is five seconds.</p>\n         <p>Example: <code>eventsPollInterval=5;</code>\n         </p>\n         <p>In the example, DMS checks for changes in the binary logs every five\n         seconds. </p>"}))
    GcpMySQLSettings.add_member(:target_db_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetDbType, location_name: 'TargetDbType', traits: {"smithy.api#documentation" => "<p>Specifies where to migrate source tables on the target, either to a single database or\n         multiple databases.</p>\n         <p>Example: <code>targetDbType=MULTIPLE_DATABASES</code>\n         </p>"}))
    GcpMySQLSettings.add_member(:max_file_size, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxFileSize', traits: {"smithy.api#documentation" => "<p>Specifies the maximum size (in KB) of any .csv file used to transfer data to a\n         MySQL-compatible database.</p>\n         <p>Example: <code>maxFileSize=512</code>\n         </p>"}))
    GcpMySQLSettings.add_member(:parallel_load_threads, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ParallelLoadThreads', traits: {"smithy.api#documentation" => "<p>Improves performance when loading data into the MySQL-compatible target database.\n         Specifies how many threads to use to load the data into the MySQL-compatible target\n         database. Setting a large number of threads can have an adverse effect on database\n         performance, because a separate connection is required for each thread. The default is\n         one.</p>\n         <p>Example: <code>parallelLoadThreads=1</code>\n         </p>"}))
    GcpMySQLSettings.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>Endpoint connection password.</p>"}))
