    IBMDb2Settings.add_member(:secrets_manager_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerSecretId', traits: {"smithy.api#documentation" => "<p>The full ARN, partial ARN, or friendly name of the <code>SecretsManagerSecret</code>\n         that contains the Db2 LUW endpoint connection details.</p>"}))
    IBMDb2Settings.add_member(:load_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'LoadTimeout', traits: {"smithy.api#documentation" => "<p>The amount of time (in milliseconds) before DMS times out operations performed by DMS\n         on the Db2 target. The default value is 1200 (20 minutes).</p>"}))
