    KafkaSettings.add_member(:broker, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Broker', traits: {"smithy.api#documentation" => "<p>A comma-separated list of one or more broker locations in your Kafka cluster that host\n         your Kafka instance. Specify each broker location in the form\n               <code>\n               <i>broker-hostname-or-ip</i>:<i>port</i>\n            </code>.\n         For example, <code>\"ec2-12-345-678-901.compute-1.amazonaws.com:2345\"</code>. For more\n         information and examples of specifying a list of broker locations, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.Kafka.html\">Using Apache\n            Kafka as a target for Database Migration Service</a> in the <i>Database Migration Service User\n         Guide</i>. </p>"}))
    KafkaSettings.add_member(:topic, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Topic', traits: {"smithy.api#documentation" => "<p>The topic to which you migrate the data. If you don't specify a topic, DMS\n         specifies <code>\"kafka-default-topic\"</code> as the migration topic.</p>"}))
    KafkaSettings.add_member(:message_format, Smithy::Schema::Shapes::ShapeRef.new(shape: MessageFormatValue, location_name: 'MessageFormat', traits: {"smithy.api#documentation" => "<p>The output format for the records created on the endpoint. The message format is\n            <code>JSON</code> (default) or <code>JSON_UNFORMATTED</code> (a single line with no\n         tab).</p>"}))
    KafkaSettings.add_member(:include_transaction_details, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludeTransactionDetails', traits: {"smithy.api#documentation" => "<p>Provides detailed transaction information from the source database. This information\n         includes a commit timestamp, a log position, and values for <code>transaction_id</code>,\n         previous <code>transaction_id</code>, and <code>transaction_record_id</code> (the record\n         offset within a transaction). The default is <code>false</code>.</p>"}))
    KafkaSettings.add_member(:include_partition_value, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludePartitionValue', traits: {"smithy.api#documentation" => "<p>Shows the partition value within the Kafka message output unless the partition type is\n            <code>schema-table-type</code>. The default is <code>false</code>.</p>"}))
    KafkaSettings.add_member(:partition_include_schema_table, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PartitionIncludeSchemaTable', traits: {"smithy.api#documentation" => "<p>Prefixes schema and table names to partition values, when the partition type is\n            <code>primary-key-type</code>. Doing this increases data distribution among Kafka\n         partitions. For example, suppose that a SysBench schema has thousands of tables and each\n         table has only limited range for a primary key. In this case, the same primary key is sent\n         from thousands of tables to the same partition, which causes throttling. The default is\n            <code>false</code>.</p>"}))
    KafkaSettings.add_member(:include_table_alter_operations, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludeTableAlterOperations', traits: {"smithy.api#documentation" => "<p>Includes any data definition language (DDL) operations that change the table in the\n         control data, such as <code>rename-table</code>, <code>drop-table</code>,\n            <code>add-column</code>, <code>drop-column</code>, and <code>rename-column</code>. The\n         default is <code>false</code>.</p>"}))
    KafkaSettings.add_member(:include_control_details, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludeControlDetails', traits: {"smithy.api#documentation" => "<p>Shows detailed control information for table definition, column definition, and table\n         and column changes in the Kafka message output. The default is <code>false</code>.</p>"}))
    KafkaSettings.add_member(:message_max_bytes, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MessageMaxBytes', traits: {"smithy.api#documentation" => "<p>The maximum size in bytes for records created on the endpoint The default is\n         1,000,000.</p>"}))
    KafkaSettings.add_member(:include_null_and_empty, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludeNullAndEmpty', traits: {"smithy.api#documentation" => "<p>Include NULL and empty columns for records migrated to the endpoint. The default is\n            <code>false</code>.</p>"}))
    KafkaSettings.add_member(:security_protocol, Smithy::Schema::Shapes::ShapeRef.new(shape: KafkaSecurityProtocol, location_name: 'SecurityProtocol', traits: {"smithy.api#documentation" => "<p>Set secure connection to a Kafka target endpoint using Transport Layer Security (TLS).\n         Options include <code>ssl-encryption</code>, <code>ssl-authentication</code>, and\n            <code>sasl-ssl</code>. <code>sasl-ssl</code> requires <code>SaslUsername</code> and\n            <code>SaslPassword</code>.</p>"}))
    KafkaSettings.add_member(:ssl_client_certificate_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SslClientCertificateArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the client certificate used to securely connect to a\n         Kafka target endpoint.</p>"}))
    KafkaSettings.add_member(:ssl_client_key_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SslClientKeyArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the client private key used to securely connect to a\n         Kafka target endpoint.</p>"}))
    KafkaSettings.add_member(:ssl_client_key_password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'SslClientKeyPassword', traits: {"smithy.api#documentation" => "<p> The password for the client private key used to securely connect to a Kafka target\n         endpoint.</p>"}))
    KafkaSettings.add_member(:ssl_ca_certificate_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SslCaCertificateArn', traits: {"smithy.api#documentation" => "<p> The Amazon Resource Name (ARN) for the private certificate authority (CA) cert that\n         DMS uses to securely connect to your Kafka target endpoint.</p>"}))
    KafkaSettings.add_member(:sasl_username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SaslUsername', traits: {"smithy.api#documentation" => "<p> The secure user name you created when you first set up your MSK cluster to validate a\n         client identity and make an encrypted connection between server and client using SASL-SSL\n         authentication.</p>"}))
    KafkaSettings.add_member(:sasl_password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'SaslPassword', traits: {"smithy.api#documentation" => "<p>The secure password you created when you first set up your MSK cluster to validate a\n         client identity and make an encrypted connection between server and client using SASL-SSL\n         authentication.</p>"}))
    KafkaSettings.add_member(:no_hex_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'NoHexPrefix', traits: {"smithy.api#documentation" => "<p>Set this optional parameter to <code>true</code> to avoid adding a '0x' prefix\n         to raw data in hexadecimal format. For example, by default, DMS adds a '0x'\n         prefix to the LOB column type in hexadecimal format moving from an Oracle source to a Kafka\n         target. Use the <code>NoHexPrefix</code> endpoint setting to enable migration of RAW data\n         type columns without adding the '0x' prefix.</p>"}))
    KafkaSettings.add_member(:sasl_mechanism, Smithy::Schema::Shapes::ShapeRef.new(shape: KafkaSaslMechanism, location_name: 'SaslMechanism', traits: {"smithy.api#documentation" => "<p>For SASL/SSL authentication, DMS supports the <code>SCRAM-SHA-512</code> mechanism by\n         default. DMS versions 3.5.0 and later also support the <code>PLAIN</code> mechanism. To\n         use the <code>PLAIN</code> mechanism, set this parameter to <code>PLAIN.</code>\n         </p>"}))
    KafkaSettings.add_member(:ssl_endpoint_identification_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: KafkaSslEndpointIdentificationAlgorithm, location_name: 'SslEndpointIdentificationAlgorithm', traits: {"smithy.api#documentation" => "<p>Sets hostname verification for the certificate. This setting is supported in DMS\n         version 3.5.1 and later. </p>"}))
    KafkaSettings.add_member(:use_large_integer_value, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseLargeIntegerValue', traits: {"smithy.api#documentation" => "<p>Specifies using the large integer value with Kafka.</p>"}))
    KafkaSettings.type = Types::KafkaSettings
    KafkaSslEndpointIdentificationAlgorithm.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NONE', traits: {"smithy.api#enumValue" => "none"}))
    KafkaSslEndpointIdentificationAlgorithm.add_member(:https, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HTTPS', traits: {"smithy.api#enumValue" => "https"}))
    KerberosAuthenticationSettings.add_member(:key_cache_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KeyCacheSecretId', traits: {"smithy.api#documentation" => "<p>Specifies the ID of the secret that stores the key cache file required for kerberos\n         authentication.</p>"}))
    KerberosAuthenticationSettings.add_member(:key_cache_secret_iam_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KeyCacheSecretIamArn', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Resource Name (ARN) of the IAM role that grants Amazon Web Services\n         DMS access to the secret containing key cache file for the kerberos authentication.</p>"}))
    KerberosAuthenticationSettings.add_member(:krb5_file_contents, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Krb5FileContents', traits: {"smithy.api#documentation" => "<p>Specifies the contents of krb5 configuration file required for kerberos\n         authentication.</p>"}))
