    KinesisSettings.add_member(:message_format, Smithy::Schema::Shapes::ShapeRef.new(shape: MessageFormatValue, location_name: 'MessageFormat', traits: {"smithy.api#documentation" => "<p>The output format for the records created on the endpoint. The message format is\n            <code>JSON</code> (default) or <code>JSON_UNFORMATTED</code> (a single line with no\n         tab).</p>"}))
    KinesisSettings.add_member(:service_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServiceAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the IAM role that DMS uses to write to the Kinesis\n         data stream. The role must allow the <code>iam:PassRole</code> action.</p>"}))
    KinesisSettings.add_member(:include_transaction_details, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludeTransactionDetails', traits: {"smithy.api#documentation" => "<p>Provides detailed transaction information from the source database. This information\n         includes a commit timestamp, a log position, and values for <code>transaction_id</code>,\n         previous <code>transaction_id</code>, and <code>transaction_record_id</code> (the record\n         offset within a transaction). The default is <code>false</code>.</p>"}))
    KinesisSettings.add_member(:include_partition_value, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludePartitionValue', traits: {"smithy.api#documentation" => "<p>Shows the partition value within the Kinesis message output, unless the partition type\n         is <code>schema-table-type</code>. The default is <code>false</code>.</p>"}))
    KinesisSettings.add_member(:partition_include_schema_table, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PartitionIncludeSchemaTable', traits: {"smithy.api#documentation" => "<p>Prefixes schema and table names to partition values, when the partition type is\n            <code>primary-key-type</code>. Doing this increases data distribution among Kinesis\n         shards. For example, suppose that a SysBench schema has thousands of tables and each table\n         has only limited range for a primary key. In this case, the same primary key is sent from\n         thousands of tables to the same shard, which causes throttling. The default is\n            <code>false</code>.</p>"}))
    KinesisSettings.add_member(:include_table_alter_operations, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludeTableAlterOperations', traits: {"smithy.api#documentation" => "<p>Includes any data definition language (DDL) operations that change the table in the\n         control data, such as <code>rename-table</code>, <code>drop-table</code>,\n            <code>add-column</code>, <code>drop-column</code>, and <code>rename-column</code>. The\n         default is <code>false</code>.</p>"}))
    KinesisSettings.add_member(:include_control_details, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludeControlDetails', traits: {"smithy.api#documentation" => "<p>Shows detailed control information for table definition, column definition, and table\n         and column changes in the Kinesis message output. The default is <code>false</code>.</p>"}))
    KinesisSettings.add_member(:include_null_and_empty, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IncludeNullAndEmpty', traits: {"smithy.api#documentation" => "<p>Include NULL and empty columns for records migrated to the endpoint. The default is\n            <code>false</code>.</p>"}))
    KinesisSettings.add_member(:no_hex_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'NoHexPrefix', traits: {"smithy.api#documentation" => "<p>Set this optional parameter to <code>true</code> to avoid adding a '0x' prefix\n         to raw data in hexadecimal format. For example, by default, DMS adds a '0x'\n         prefix to the LOB column type in hexadecimal format moving from an Oracle source to an\n         Amazon Kinesis target. Use the <code>NoHexPrefix</code> endpoint setting to enable\n         migration of RAW data type columns without adding the '0x' prefix.</p>"}))
    KinesisSettings.add_member(:use_large_integer_value, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseLargeIntegerValue', traits: {"smithy.api#documentation" => "<p>Specifies using the large integer value with Kinesis.</p>"}))
