    Limitation.add_member(:engine_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineName', traits: {"smithy.api#documentation" => "<p>The name of the target engine that Fleet Advisor should use in the target engine\n            recommendation. Valid values include <code>\"rds-aurora-mysql\"</code>,\n                <code>\"rds-aurora-postgresql\"</code>, <code>\"rds-mysql\"</code>,\n                <code>\"rds-oracle\"</code>, <code>\"rds-sql-server\"</code>, and\n                <code>\"rds-postgresql\"</code>.</p>"}))
    Limitation.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the limitation. Describes unsupported database features, migration action\n            items, and other limitations.</p>"}))
    Limitation.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the limitation. Provides additional information about the limitation,\n            and includes recommended actions that you can take to address or avoid this\n            limitation.</p>"}))
    Limitation.add_member(:impact, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Impact', traits: {"smithy.api#documentation" => "<p>The impact of the limitation. You can use this parameter to prioritize limitations\n            that you want to address. Valid values include <code>\"Blocker\"</code>,\n                <code>\"High\"</code>, <code>\"Medium\"</code>, and <code>\"Low\"</code>.</p>"}))
    Limitation.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>The type of the limitation, such as action required, upgrade required, and limited\n            feature.</p>"}))
    Limitation.type = Types::Limitation
