    ListTagsForResourceMessage.add_member(:resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResourceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) string that uniquely identifies the DMS resource to\n         list tags for. This returns a list of keys (names of tags) created for the resource and\n         their associated tag values.</p>"}))
    ListTagsForResourceMessage.add_member(:resource_arn_list, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnList, location_name: 'ResourceArnList', traits: {"smithy.api#documentation" => "<p>List of ARNs that identify multiple DMS resources that you want to list tags for. This\n         returns a list of keys (tag names) and their associated tag values. It also returns each\n         tag's associated <code>ResourceArn</code> value, which is the ARN of the resource for which\n         each listed tag is created. </p>"}))
    ListTagsForResourceMessage.type = Types::ListTagsForResourceMessage
