    MariaDbDataProviderSettings.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port value for the MariaDB data provider</p>"}))
    MariaDbDataProviderSettings.add_member(:ssl_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DmsSslModeValue, location_name: 'SslMode', traits: {"smithy.api#documentation" => "<p>The SSL mode used to connect to the MariaDB data provider. \n         The default value is <code>none</code>.</p>"}))
    MariaDbDataProviderSettings.add_member(:certificate_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CertificateArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the certificate used for SSL connection.</p>"}))
    MariaDbDataProviderSettings.add_member(:s3_path, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3Path', traits: {"smithy.api#documentation" => "<p>The path for the Amazon S3 bucket that the application uses for accessing the user-defined schema.</p>"}))
