    MariaDbDataProviderSettings.type = Types::MariaDbDataProviderSettings
    MessageFormatValue.add_member(:json, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'JSON', traits: {"smithy.api#enumValue" => "json"}))
    MessageFormatValue.add_member(:json_unformatted, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'JSON_UNFORMATTED', traits: {"smithy.api#enumValue" => "json-unformatted"}))
    MicrosoftSQLServerSettings.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>Endpoint TCP port.</p>"}))
    MicrosoftSQLServerSettings.add_member(:bcp_packet_size, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BcpPacketSize', traits: {"smithy.api#documentation" => "<p>The maximum size of the packets (in bytes) used to transfer data using BCP.</p>"}))
    MicrosoftSQLServerSettings.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>Database name for the endpoint.</p>"}))
    MicrosoftSQLServerSettings.add_member(:control_tables_file_group, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ControlTablesFileGroup', traits: {"smithy.api#documentation" => "<p>Specifies a file group for the DMS internal tables. When the replication task starts,\n         all the internal DMS control tables (awsdms_ apply_exception, awsdms_apply,\n         awsdms_changes) are created for the specified file group.</p>"}))
    MicrosoftSQLServerSettings.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>Endpoint connection password.</p>"}))
    MicrosoftSQLServerSettings.add_member(:query_single_always_on_node, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'QuerySingleAlwaysOnNode', traits: {"smithy.api#documentation" => "<p>Cleans and recreates table metadata information on the replication instance when a\n         mismatch occurs. An example is a situation where running an alter DDL statement on a table\n         might result in different information about the table cached in the replication\n         instance.</p>"}))
    MicrosoftSQLServerSettings.add_member(:read_backup_only, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ReadBackupOnly', traits: {"smithy.api#documentation" => "<p>When this attribute is set to <code>Y</code>, DMS only reads changes from transaction\n         log backups and doesn't read from the active transaction log file during ongoing\n         replication. Setting this parameter to <code>Y</code> enables you to control active\n         transaction log file growth during full load and ongoing replication tasks. However, it can\n         add some source latency to ongoing replication.</p>"}))
    MicrosoftSQLServerSettings.add_member(:safeguard_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: SafeguardPolicy, location_name: 'SafeguardPolicy', traits: {"smithy.api#documentation" => "<p>Use this attribute to minimize the need to access the backup log and enable DMS to\n         prevent truncation using one of the following two methods.</p>\n         <p>\n            <i>Start transactions in the database:</i> This is the default method.\n         When this method is used, DMS prevents TLOG truncation by mimicking a transaction in the\n         database. As long as such a transaction is open, changes that appear after the transaction\n         started aren't truncated. If you need Microsoft Replication to be enabled in your database,\n         then you must choose this method.</p>\n         <p>\n            <i>Exclusively use sp_repldone within a single task</i>: When this method\n         is used, DMS reads the changes and then uses sp_repldone to mark the TLOG transactions as\n         ready for truncation. Although this method doesn't involve any transactional activities, it\n         can only be used when Microsoft Replication isn't running. Also, when using this method,\n         only one DMS task can access the database at any given time. Therefore, if you need to\n         run parallel DMS tasks against the same database, use the default method.</p>"}))
    MicrosoftSQLServerSettings.add_member(:server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerName', traits: {"smithy.api#documentation" => "<p>Fully qualified domain name of the endpoint. For an Amazon RDS SQL Server instance, this is\n         the output of <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_DescribeDBInstances.html\">DescribeDBInstances</a>, in the <code>\n               <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_Endpoint.html\">Endpoint</a>.Address</code> field.</p>"}))
    MicrosoftSQLServerSettings.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>Endpoint connection user name.</p>"}))
    MicrosoftSQLServerSettings.add_member(:use_bcp_full_load, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseBcpFullLoad', traits: {"smithy.api#documentation" => "<p>Use this to attribute to transfer data for full-load operations using BCP. When the\n         target table contains an identity column that does not exist in the source table, you must\n         disable the use BCP for loading table option.</p>"}))
    MicrosoftSQLServerSettings.add_member(:use_third_party_backup_device, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseThirdPartyBackupDevice', traits: {"smithy.api#documentation" => "<p>When this attribute is set to <code>Y</code>, DMS processes third-party transaction log\n         backups if they are created in native format.</p>"}))
    MicrosoftSQLServerSettings.add_member(:secrets_manager_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The full Amazon Resource Name (ARN) of the IAM role that specifies DMS as the trusted\n         entity and grants the required permissions to access the value in\n            <code>SecretsManagerSecret</code>. The role must allow the <code>iam:PassRole</code>\n         action. <code>SecretsManagerSecret</code> has the value of the Amazon Web Services Secrets Manager secret that\n         allows access to the SQL Server endpoint.</p>\n         <note>\n            <p>You can specify one of two sets of values for these permissions. You can specify the\n            values for this setting and <code>SecretsManagerSecretId</code>. Or you can specify\n            clear-text values for <code>UserName</code>, <code>Password</code>,\n               <code>ServerName</code>, and <code>Port</code>. You can't specify both. For more\n            information on creating this <code>SecretsManagerSecret</code> and the\n               <code>SecretsManagerAccessRoleArn</code> and <code>SecretsManagerSecretId</code>\n            required to access it, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Security.html#security-iam-secretsmanager\">Using secrets to access Database Migration Service resources</a> in the\n               <i>Database Migration Service User Guide</i>.</p>\n         </note>"}))
