    MicrosoftSQLServerSettings.add_member(:trim_space_in_char, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'TrimSpaceInChar', traits: {"smithy.api#documentation" => "<p>Use the <code>TrimSpaceInChar</code> source endpoint setting to right-trim data on CHAR\n         and NCHAR data types during migration. Setting <code>TrimSpaceInChar</code> does not\n         left-trim data. The default value is <code>true</code>.</p>"}))
