    ModifyEndpointMessage.add_member(:kafka_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: KafkaSettings, location_name: 'KafkaSettings', traits: {"smithy.api#documentation" => "<p>Settings in JSON format for the target Apache Kafka endpoint. For more information about\n         the available settings, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.Kafka.html#CHAP_Target.Kafka.ObjectMapping\">Using\n            object mapping to migrate data to a Kafka topic</a> in the <i>Database Migration Service User\n            Guide.</i>\n         </p>"}))
