    ModifyReplicationInstanceMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range (in UTC) during which system maintenance can occur, which might\n         result in an outage. Changing this parameter does not result in an outage, except in the\n         following situation, and the change is asynchronously applied as soon as possible. If\n         moving this window to the current time, there must be at least 30 minutes between the\n         current time and end of the window to ensure pending changes are applied.</p>\n         <p>Default: Uses existing setting</p>\n         <p>Format: ddd:hh24:mi-ddd:hh24:mi</p>\n         <p>Valid Days: Mon | Tue | Wed | Thu | Fri | Sat | Sun</p>\n         <p>Constraints: Must be at least 30 minutes</p>"}))
    ModifyReplicationInstanceMessage.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p> Specifies whether the replication instance is a Multi-AZ deployment. You can't set\n         the <code>AvailabilityZone</code> parameter if the Multi-AZ parameter is set to\n            <code>true</code>. </p>"}))
    ModifyReplicationInstanceMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The engine version number of the replication instance.</p>\n         <p>When modifying a major engine version of an instance, also set\n            <code>AllowMajorVersionUpgrade</code> to <code>true</code>.</p>"}))
    ModifyReplicationInstanceMessage.add_member(:allow_major_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AllowMajorVersionUpgrade', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates that major version upgrades are allowed. Changing this parameter does not\n         result in an outage, and the change is asynchronously applied as soon as possible.</p>\n         <p>This parameter must be set to <code>true</code> when specifying a value for the\n            <code>EngineVersion</code> parameter that is a different major version than the\n         replication instance's current version.</p>"}))
    ModifyReplicationInstanceMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>A value that indicates that minor version upgrades are applied automatically to the\n         replication instance during the maintenance window. Changing this parameter doesn't result\n         in an outage, except in the case described following. The change is asynchronously applied\n         as soon as possible. </p>\n         <p>An outage does result if these factors apply: </p>\n         <ul>\n            <li>\n               <p>This parameter is set to <code>true</code> during the maintenance window.</p>\n            </li>\n            <li>\n               <p>A newer minor version is available. </p>\n            </li>\n            <li>\n               <p>DMS has enabled automatic patching for the given engine version. </p>\n            </li>\n         </ul>"}))
