    ModifyReplicationTaskMessage.add_member(:migration_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MigrationTypeValue, location_name: 'MigrationType', traits: {"smithy.api#documentation" => "<p>The migration type. Valid values: <code>full-load</code> | <code>cdc</code> |\n            <code>full-load-and-cdc</code>\n         </p>"}))
    ModifyReplicationTaskMessage.add_member(:table_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TableMappings', traits: {"smithy.api#documentation" => "<p>When using the CLI or boto3, provide the path of the JSON file that contains the table\n         mappings. Precede the path with <code>file://</code>. For example, <code>--table-mappings\n            file://mappingfile.json</code>. When working with the DMS API, provide the JSON as the\n         parameter value. </p>"}))
    ModifyReplicationTaskMessage.add_member(:replication_task_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationTaskSettings', traits: {"smithy.api#documentation" => "<p>JSON file that contains settings for the task, such as task metadata settings.</p>"}))
    ModifyReplicationTaskMessage.add_member(:cdc_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'CdcStartTime', traits: {"smithy.api#documentation" => "<p>Indicates the start time for a change data capture (CDC) operation. Use either\n         CdcStartTime or CdcStartPosition to specify when you want a CDC operation to start.\n         Specifying both values results in an error.</p>\n         <p>Timestamp Example: --cdc-start-time “2018-03-08T12:12:12”</p>"}))
    ModifyReplicationTaskMessage.add_member(:cdc_start_position, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CdcStartPosition', traits: {"smithy.api#documentation" => "<p>Indicates when you want a change data capture (CDC) operation to start. Use either\n         CdcStartPosition or CdcStartTime to specify when you want a CDC operation to start.\n         Specifying both values results in an error.</p>\n         <p> The value can be in date, checkpoint, or LSN/SCN format.</p>\n         <p>Date Example: --cdc-start-position “2018-03-08T12:12:12”</p>\n         <p>Checkpoint Example: --cdc-start-position\n         \"checkpoint:V1#27#mysql-bin-changelog.157832:1975:-1:2002:677883278264080:mysql-bin-changelog.157832:1876#0#0#*#0#93\"</p>\n         <p>LSN Example: --cdc-start-position “mysql-bin-changelog.000024:373”</p>\n         <note>\n            <p>When you use this task setting with a source PostgreSQL database, a logical\n            replication slot should already be created and associated with the source endpoint. You\n            can verify this by setting the <code>slotName</code> extra connection attribute to the\n            name of this logical replication slot. For more information, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.PostgreSQL.html#CHAP_Source.PostgreSQL.ConnectionAttrib\">Extra Connection Attributes When Using PostgreSQL as a Source\n               for DMS</a>.</p>\n         </note>"}))
    ModifyReplicationTaskMessage.add_member(:cdc_stop_position, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CdcStopPosition', traits: {"smithy.api#documentation" => "<p>Indicates when you want a change data capture (CDC) operation to stop. The value can be\n         either server time or commit time.</p>\n         <p>Server time example: --cdc-stop-position “server_time:2018-02-09T12:12:12”</p>\n         <p>Commit time example: --cdc-stop-position “commit_time:2018-02-09T12:12:12“</p>"}))
    ModifyReplicationTaskMessage.add_member(:task_data, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TaskData', traits: {"smithy.api#documentation" => "<p>Supplemental information that the task requires to migrate the data for certain source\n         and target endpoints. For more information, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Tasks.TaskData.html\">Specifying Supplemental Data for\n            Task Settings</a> in the <i>Database Migration Service User Guide.</i>\n         </p>"}))
