    MongoDbDataProviderSettings.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port value for the MongoDB data provider.</p>"}))
    MongoDbDataProviderSettings.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The database name on the MongoDB data provider.</p>"}))
    MongoDbDataProviderSettings.add_member(:ssl_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DmsSslModeValue, location_name: 'SslMode', traits: {"smithy.api#documentation" => "<p>The SSL mode used to connect to the MongoDB data provider. \n         The default value is <code>none</code>.</p>"}))
    MongoDbDataProviderSettings.add_member(:certificate_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CertificateArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the certificate used for SSL connection.</p>"}))
    MongoDbDataProviderSettings.add_member(:auth_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AuthTypeValue, location_name: 'AuthType', traits: {"smithy.api#documentation" => "<p>The authentication type for the database connection. Valid values are PASSWORD or NO.</p>"}))
    MongoDbDataProviderSettings.add_member(:auth_source, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AuthSource', traits: {"smithy.api#documentation" => "<p> The MongoDB database name. This setting isn't used when <code>AuthType</code> is\n         set to <code>\"no\"</code>. </p>\n         <p>The default is <code>\"admin\"</code>.</p>"}))
    MongoDbDataProviderSettings.add_member(:auth_mechanism, Smithy::Schema::Shapes::ShapeRef.new(shape: AuthMechanismValue, location_name: 'AuthMechanism', traits: {"smithy.api#documentation" => "<p>The authentication method for connecting to the data provider. Valid values are DEFAULT, MONGODB_CR, or SCRAM_SHA_1.</p>"}))
    MongoDbDataProviderSettings.type = Types::MongoDbDataProviderSettings
    MongoDbSettings.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>The user name you use to access the MongoDB source endpoint. </p>"}))
    MongoDbSettings.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'Password', traits: {"smithy.api#documentation" => "<p> The password for the user account you use to access the MongoDB source endpoint.\n      </p>"}))
    MongoDbSettings.add_member(:server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerName', traits: {"smithy.api#documentation" => "<p> The name of the server on the MongoDB source endpoint. For MongoDB Atlas, provide the\n         server name for any of the servers in the replication set.</p>"}))
    MongoDbSettings.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p> The port value for the MongoDB source endpoint. </p>"}))
    MongoDbSettings.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p> The database name on the MongoDB source endpoint. </p>"}))
    MongoDbSettings.add_member(:auth_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AuthTypeValue, location_name: 'AuthType', traits: {"smithy.api#documentation" => "<p> The authentication type you use to access the MongoDB source endpoint.</p>\n         <p>When when set to <code>\"no\"</code>, user name and password parameters are not used and\n         can be empty. </p>"}))
    MongoDbSettings.add_member(:auth_mechanism, Smithy::Schema::Shapes::ShapeRef.new(shape: AuthMechanismValue, location_name: 'AuthMechanism', traits: {"smithy.api#documentation" => "<p> The authentication mechanism you use to access the MongoDB source endpoint.</p>\n         <p>For the default value, in MongoDB version 2.x, <code>\"default\"</code> is\n            <code>\"mongodb_cr\"</code>. For MongoDB version 3.x or later, <code>\"default\"</code> is\n            <code>\"scram_sha_1\"</code>. This setting isn't used when <code>AuthType</code> is\n         set to <code>\"no\"</code>.</p>"}))
    MongoDbSettings.add_member(:nesting_level, Smithy::Schema::Shapes::ShapeRef.new(shape: NestingLevelValue, location_name: 'NestingLevel', traits: {"smithy.api#documentation" => "<p> Specifies either document or table mode. </p>\n         <p>Default value is <code>\"none\"</code>. Specify <code>\"none\"</code> to use document mode.\n         Specify <code>\"one\"</code> to use table mode.</p>"}))
    MongoDbSettings.add_member(:extract_doc_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ExtractDocId', traits: {"smithy.api#documentation" => "<p> Specifies the document ID. Use this setting when <code>NestingLevel</code> is set to\n            <code>\"none\"</code>. </p>\n         <p>Default value is <code>\"false\"</code>. </p>"}))
    MongoDbSettings.add_member(:docs_to_investigate, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DocsToInvestigate', traits: {"smithy.api#documentation" => "<p> Indicates the number of documents to preview to determine the document organization.\n         Use this setting when <code>NestingLevel</code> is set to <code>\"one\"</code>. </p>\n         <p>Must be a positive value greater than <code>0</code>. Default value is\n         <code>1000</code>.</p>"}))
    MongoDbSettings.add_member(:auth_source, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AuthSource', traits: {"smithy.api#documentation" => "<p> The MongoDB database name. This setting isn't used when <code>AuthType</code> is\n         set to <code>\"no\"</code>. </p>\n         <p>The default is <code>\"admin\"</code>.</p>"}))
    MongoDbSettings.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The KMS key identifier that is used to encrypt the content on the replication\n         instance. If you don't specify a value for the <code>KmsKeyId</code> parameter, then DMS\n         uses your default encryption key. KMS creates the default encryption key for your\n         Amazon Web Services account. Your Amazon Web Services account has a different default encryption key for each\n         Amazon Web Services Region.</p>"}))
    MongoDbSettings.add_member(:secrets_manager_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The full Amazon Resource Name (ARN) of the IAM role that specifies DMS as the trusted\n         entity and grants the required permissions to access the value in\n            <code>SecretsManagerSecret</code>. The role must allow the <code>iam:PassRole</code>\n         action. <code>SecretsManagerSecret</code> has the value of the Amazon Web Services Secrets Manager secret that\n         allows access to the MongoDB endpoint.</p>\n         <note>\n            <p>You can specify one of two sets of values for these permissions. You can specify the\n            values for this setting and <code>SecretsManagerSecretId</code>. Or you can specify\n            clear-text values for <code>UserName</code>, <code>Password</code>,\n               <code>ServerName</code>, and <code>Port</code>. You can't specify both. For more\n            information on creating this <code>SecretsManagerSecret</code> and the\n               <code>SecretsManagerAccessRoleArn</code> and <code>SecretsManagerSecretId</code>\n            required to access it, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Security.html#security-iam-secretsmanager\">Using secrets to access Database Migration Service resources</a> in the\n               <i>Database Migration Service User Guide</i>.</p>\n         </note>"}))
    MongoDbSettings.add_member(:secrets_manager_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerSecretId', traits: {"smithy.api#documentation" => "<p>The full ARN, partial ARN, or friendly name of the <code>SecretsManagerSecret</code>\n         that contains the MongoDB endpoint connection details.</p>"}))
    MongoDbSettings.add_member(:use_update_look_up, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseUpdateLookUp', traits: {"smithy.api#documentation" => "<p>If <code>true</code>, DMS retrieves the entire document from the MongoDB source during migration.\n         This may cause a migration failure if the server response exceeds bandwidth limits. To fetch only updates\n         and deletes during migration, set this parameter to <code>false</code>.</p>"}))
    MongoDbSettings.add_member(:replicate_shard_collections, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ReplicateShardCollections', traits: {"smithy.api#documentation" => "<p>If <code>true</code>, DMS replicates data to shard collections. DMS only uses this\n         setting if the target endpoint is a DocumentDB elastic cluster.</p>\n         <p>When this setting is <code>true</code>, note the following:</p>\n         <ul>\n            <li>\n               <p>You must set <code>TargetTablePrepMode</code> to <code>nothing</code>.</p>\n            </li>\n            <li>\n               <p>DMS automatically sets <code>useUpdateLookup</code> to\n               <code>false</code>.</p>\n            </li>\n         </ul>"}))
    MongoDbSettings.type = Types::MongoDbSettings
