    MySQLSettings.add_member(:after_connect_script, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AfterConnectScript', traits: {"smithy.api#documentation" => "<p>Specifies a script to run immediately after DMS connects to the endpoint. The\n         migration task continues running regardless if the SQL statement succeeds or fails.</p>\n         <p>For this parameter, provide the code of the script itself, not the name of a file\n         containing the script.</p>"}))
    MySQLSettings.add_member(:clean_source_metadata_on_mismatch, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CleanSourceMetadataOnMismatch', traits: {"smithy.api#documentation" => "<p>Cleans and recreates table metadata information on the replication instance when a\n         mismatch occurs. For example, in a situation where running an alter DDL on the table could\n         result in different information about the table cached in the replication instance. </p>"}))
    MySQLSettings.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>Database name for the endpoint. For a MySQL source or target endpoint, don't explicitly\n         specify the database using the <code>DatabaseName</code> request parameter on either the\n            <code>CreateEndpoint</code> or <code>ModifyEndpoint</code> API call. Specifying\n            <code>DatabaseName</code> when you create or modify a MySQL endpoint replicates all the\n         task tables to this single database. For MySQL endpoints, you specify the database only\n         when you specify the schema in the table-mapping rules of the DMS task.</p>"}))
    MySQLSettings.add_member(:events_poll_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'EventsPollInterval', traits: {"smithy.api#documentation" => "<p>Specifies how often to check the binary log for new changes/events when the database is\n         idle. The default is five seconds.</p>\n         <p>Example: <code>eventsPollInterval=5;</code>\n         </p>\n         <p>In the example, DMS checks for changes in the binary logs every five seconds.</p>"}))
    MySQLSettings.add_member(:target_db_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetDbType, location_name: 'TargetDbType', traits: {"smithy.api#documentation" => "<p>Specifies where to migrate source tables on the target, either to a single database or\n         multiple databases. If you specify <code>SPECIFIC_DATABASE</code>, specify the database\n         name using the <code>DatabaseName</code> parameter of the <code>Endpoint</code>\n         object.</p>\n         <p>Example: <code>targetDbType=MULTIPLE_DATABASES</code>\n         </p>"}))
    MySQLSettings.add_member(:max_file_size, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxFileSize', traits: {"smithy.api#documentation" => "<p>Specifies the maximum size (in KB) of any .csv file used to transfer data to a\n         MySQL-compatible database.</p>\n         <p>Example: <code>maxFileSize=512</code>\n         </p>"}))
    MySQLSettings.add_member(:parallel_load_threads, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ParallelLoadThreads', traits: {"smithy.api#documentation" => "<p>Improves performance when loading data into the MySQL-compatible target database.\n         Specifies how many threads to use to load the data into the MySQL-compatible target\n         database. Setting a large number of threads can have an adverse effect on database\n         performance, because a separate connection is required for each thread. The default is\n         one.</p>\n         <p>Example: <code>parallelLoadThreads=1</code>\n         </p>"}))
    MySQLSettings.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>Endpoint connection password.</p>"}))
    MySQLSettings.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>Endpoint TCP port.</p>"}))
    MySQLSettings.add_member(:server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerName', traits: {"smithy.api#documentation" => "<p>The host name of the endpoint database. </p>\n         <p>For an Amazon RDS MySQL instance, this is the output of <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_DescribeDBInstances.html\">DescribeDBInstances</a>, in the <code>\n               <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_Endpoint.html\">Endpoint</a>.Address</code> field.</p>\n         <p>For an Aurora MySQL instance, this is the output of <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_DescribeDBClusters.html\">DescribeDBClusters</a>, in the <code>Endpoint</code> field.</p>"}))
    MySQLSettings.add_member(:server_timezone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerTimezone', traits: {"smithy.api#documentation" => "<p>Specifies the time zone for the source MySQL database.</p>\n         <p>Example: <code>serverTimezone=US/Pacific;</code>\n         </p>\n         <p>Note: Do not enclose time zones in single quotes.</p>"}))
    MySQLSettings.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>Endpoint connection user name.</p>"}))
    MySQLSettings.add_member(:secrets_manager_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The full Amazon Resource Name (ARN) of the IAM role that specifies DMS as the trusted\n         entity and grants the required permissions to access the value in\n            <code>SecretsManagerSecret</code>. The role must allow the <code>iam:PassRole</code>\n         action. <code>SecretsManagerSecret</code> has the value of the Amazon Web Services Secrets Manager secret that\n         allows access to the MySQL endpoint.</p>\n         <note>\n            <p>You can specify one of two sets of values for these permissions. You can specify the\n            values for this setting and <code>SecretsManagerSecretId</code>. Or you can specify\n            clear-text values for <code>UserName</code>, <code>Password</code>,\n               <code>ServerName</code>, and <code>Port</code>. You can't specify both. For more\n            information on creating this <code>SecretsManagerSecret</code> and the\n               <code>SecretsManagerAccessRoleArn</code> and <code>SecretsManagerSecretId</code>\n            required to access it, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Security.html#security-iam-secretsmanager\">Using secrets to access Database Migration Service resources</a> in the\n               <i>Database Migration Service User Guide</i>.</p>\n         </note>"}))
    MySQLSettings.add_member(:secrets_manager_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerSecretId', traits: {"smithy.api#documentation" => "<p>The full ARN, partial ARN, or friendly name of the <code>SecretsManagerSecret</code>\n         that contains the MySQL endpoint connection details.</p>"}))
    MySQLSettings.add_member(:execute_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ExecuteTimeout', traits: {"smithy.api#documentation" => "<p>Sets the client statement timeout (in seconds) for a MySQL source endpoint.</p>"}))
    MySQLSettings.add_member(:service_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServiceAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The IAM role you can use to authenticate when connecting to your endpoint. Ensure to include <code>iam:PassRole</code> and <code>rds-db:connect</code> actions in permission policy.</p>"}))
    MySQLSettings.add_member(:authentication_method, Smithy::Schema::Shapes::ShapeRef.new(shape: MySQLAuthenticationMethod, location_name: 'AuthenticationMethod', traits: {"smithy.api#documentation" => "<p>This attribute allows you to specify the authentication method as \"iam auth\".</p>"}))
    MySQLSettings.type = Types::MySQLSettings
