    NeptuneSettings.add_member(:service_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServiceAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the service role that you created for the Neptune\n         target endpoint. The role must allow the <code>iam:PassRole</code> action. For more\n         information, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Target.Neptune.html#CHAP_Target.Neptune.ServiceRole\">Creating an IAM Service Role for Accessing Amazon Neptune as a\n            Target</a> in the <i>Database Migration Service User Guide. </i>\n         </p>"}))
    NeptuneSettings.add_member(:s3_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3BucketName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon S3 bucket where DMS can temporarily store migrated graph data\n         in .csv files before bulk-loading it to the Neptune target database. DMS maps the SQL\n         source data to graph data before storing it in these .csv files.</p>", "smithy.api#required" => {}}))
    NeptuneSettings.add_member(:s3_bucket_folder, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3BucketFolder', traits: {"smithy.api#documentation" => "<p>A folder path where you want DMS to store migrated graph data in the S3 bucket\n         specified by <code>S3BucketName</code>\n         </p>", "smithy.api#required" => {}}))
    NeptuneSettings.add_member(:error_retry_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ErrorRetryDuration', traits: {"smithy.api#documentation" => "<p>The number of milliseconds for DMS to wait to retry a bulk-load of migrated graph data\n         to the Neptune target database before raising an error. The default is 250.</p>"}))
    NeptuneSettings.add_member(:max_file_size, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxFileSize', traits: {"smithy.api#documentation" => "<p>The maximum size in kilobytes of migrated graph data stored in a .csv file before DMS\n         bulk-loads the data to the Neptune target database. The default is 1,048,576 KB. If the\n         bulk load is successful, DMS clears the bucket, ready to store the next batch of migrated\n         graph data.</p>"}))
    NeptuneSettings.add_member(:max_retry_count, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxRetryCount', traits: {"smithy.api#documentation" => "<p>The number of times for DMS to retry a bulk load of migrated graph data to the Neptune\n         target database before raising an error. The default is 5.</p>"}))
    NeptuneSettings.add_member(:iam_auth_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IamAuthEnabled', traits: {"smithy.api#documentation" => "<p>If you want Identity and Access Management (IAM) authorization enabled for this endpoint, set this parameter\n         to <code>true</code>. Then attach the appropriate IAM policy document to your service role\n         specified by <code>ServiceAccessRoleArn</code>. The default is <code>false</code>.</p>"}))
    NeptuneSettings.type = Types::NeptuneSettings
    NestingLevelValue.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NONE', traits: {"smithy.api#enumValue" => "none"}))
    NestingLevelValue.add_member(:one, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ONE', traits: {"smithy.api#enumValue" => "one"}))
    OracleAuthenticationMethod.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Password', traits: {"smithy.api#enumValue" => "password"}))
    OracleAuthenticationMethod.add_member(:kerberos, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Kerberos', traits: {"smithy.api#enumValue" => "kerberos"}))
    OracleDataProviderSettings.add_member(:server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerName', traits: {"smithy.api#documentation" => "<p>The name of the Oracle server.</p>"}))
    OracleDataProviderSettings.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port value for the Oracle data provider.</p>"}))
    OracleDataProviderSettings.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The database name on the Oracle data provider.</p>"}))
    OracleDataProviderSettings.add_member(:ssl_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DmsSslModeValue, location_name: 'SslMode', traits: {"smithy.api#documentation" => "<p>The SSL mode used to connect to the Oracle data provider. \n         The default value is <code>none</code>.</p>"}))
    OracleDataProviderSettings.add_member(:certificate_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CertificateArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the certificate used for SSL connection.</p>"}))
    OracleDataProviderSettings.add_member(:asm_server, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AsmServer', traits: {"smithy.api#documentation" => "<p>The address of your Oracle Automatic Storage Management (ASM) server. You can set \n         this value from the <code>asm_server</code> value. You set <code>asm_server</code> as part \n         of the extra connection attribute string to access an Oracle server with Binary Reader that \n         uses ASM. For more information, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.Oracle.html#dms/latest/userguide/CHAP_Source.Oracle.html#CHAP_Source.Oracle.CDC.Configuration\">Configuration for change data capture (CDC) on an Oracle source database</a>.</p>"}))
    OracleDataProviderSettings.add_member(:secrets_manager_oracle_asm_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerOracleAsmSecretId', traits: {"smithy.api#documentation" => "<p>The identifier of the secret in Secrets Manager that contains the Oracle ASM connection details.</p>\n         <p>Required only if your data provider uses the Oracle ASM server.</p>"}))
    OracleDataProviderSettings.add_member(:secrets_manager_oracle_asm_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerOracleAsmAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that provides access to the secret in Secrets Manager \n         that contains the Oracle ASM connection details.</p>"}))
    OracleDataProviderSettings.add_member(:secrets_manager_security_db_encryption_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerSecurityDbEncryptionSecretId', traits: {"smithy.api#documentation" => "<p>The identifier of the secret in Secrets Manager that contains the transparent data encryption (TDE) \n         password. DMS requires this password to access Oracle redo logs encrypted by TDE \n         using Binary Reader.</p>"}))
    OracleDataProviderSettings.add_member(:secrets_manager_security_db_encryption_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerSecurityDbEncryptionAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that provides access to the secret in Secrets Manager \n         that contains the TDE password.</p>"}))
    OracleDataProviderSettings.add_member(:s3_path, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3Path', traits: {"smithy.api#documentation" => "<p>The path for the Amazon S3 bucket that the application uses for accessing the user-defined schema.</p>"}))
    OracleDataProviderSettings.add_member(:s3_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3AccessRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN for the role the application uses to access its Amazon S3 bucket.</p>"}))
    OracleDataProviderSettings.type = Types::OracleDataProviderSettings
    OracleSettings.add_member(:add_supplemental_logging, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AddSupplementalLogging', traits: {"smithy.api#documentation" => "<p>Set this attribute to set up table-level supplemental logging for the Oracle database.\n         This attribute enables PRIMARY KEY supplemental logging on all tables selected for a\n         migration task.</p>\n         <p>If you use this option, you still need to enable database-level supplemental\n         logging.</p>"}))
    OracleSettings.add_member(:archived_log_dest_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ArchivedLogDestId', traits: {"smithy.api#documentation" => "<p>Specifies the ID of the destination for the archived redo logs. This value should be the\n         same as a number in the dest_id column of the v$archived_log view. If you work with an\n         additional redo log destination, use the <code>AdditionalArchivedLogDestId</code> option to\n         specify the additional destination ID. Doing this improves performance by ensuring that the\n         correct logs are accessed from the outset.</p>"}))
    OracleSettings.add_member(:additional_archived_log_dest_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AdditionalArchivedLogDestId', traits: {"smithy.api#documentation" => "<p>Set this attribute with <code>ArchivedLogDestId</code> in a primary/ standby setup. This\n         attribute is useful in the case of a switchover. In this case, DMS needs to know which\n         destination to get archive redo logs from to read changes. This need arises because the\n         previous primary instance is now a standby instance after switchover.</p>\n         <p>Although DMS supports the use of the Oracle <code>RESETLOGS</code> option to open the\n         database, never use <code>RESETLOGS</code> unless necessary. For additional information\n         about <code>RESETLOGS</code>, see <a href=\"https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-data-repair-concepts.html#GUID-1805CCF7-4AF2-482D-B65A-998192F89C2B\">RMAN Data Repair Concepts</a> in the <i>Oracle Database Backup and Recovery\n            User's Guide</i>.</p>"}))
    OracleSettings.add_member(:extra_archived_log_dest_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerList, location_name: 'ExtraArchivedLogDestIds', traits: {"smithy.api#documentation" => "<p>Specifies the IDs of one more destinations for one or more archived redo logs. These IDs\n         are the values of the <code>dest_id</code> column in the <code>v$archived_log</code> view.\n         Use this setting with the <code>archivedLogDestId</code> extra connection attribute in a\n         primary-to-single setup or a primary-to-multiple-standby setup. </p>\n         <p>This setting is useful in a switchover when you use an Oracle Data Guard database as a\n         source. In this case, DMS needs information about what destination to get archive redo\n         logs from to read changes. DMS needs this because after the switchover the previous\n         primary is a standby instance. For example, in a primary-to-single standby setup you might\n         apply the following settings. </p>\n         <p>\n            <code>archivedLogDestId=1; ExtraArchivedLogDestIds=[2]</code>\n         </p>\n         <p>In a primary-to-multiple-standby setup, you might apply the following settings.</p>\n         <p>\n            <code>archivedLogDestId=1; ExtraArchivedLogDestIds=[2,3,4]</code>\n         </p>\n         <p>Although DMS supports the use of the Oracle <code>RESETLOGS</code> option to open the\n         database, never use <code>RESETLOGS</code> unless it's necessary. For more information\n         about <code>RESETLOGS</code>, see <a href=\"https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-data-repair-concepts.html#GUID-1805CCF7-4AF2-482D-B65A-998192F89C2B\"> RMAN Data Repair Concepts</a> in the <i>Oracle Database Backup and Recovery\n            User's Guide</i>.</p>"}))
    OracleSettings.add_member(:allow_select_nested_tables, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AllowSelectNestedTables', traits: {"smithy.api#documentation" => "<p>Set this attribute to <code>true</code> to enable replication of Oracle tables\n         containing columns that are nested tables or defined types.</p>"}))
    OracleSettings.add_member(:parallel_asm_read_threads, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ParallelAsmReadThreads', traits: {"smithy.api#documentation" => "<p>Set this attribute to change the number of threads that DMS configures to perform a\n         change data capture (CDC) load using Oracle Automatic Storage Management (ASM). You can\n         specify an integer value between 2 (the default) and 8 (the maximum). Use this attribute\n         together with the <code>readAheadBlocks</code> attribute.</p>"}))
    OracleSettings.add_member(:read_ahead_blocks, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ReadAheadBlocks', traits: {"smithy.api#documentation" => "<p>Set this attribute to change the number of read-ahead blocks that DMS configures to\n         perform a change data capture (CDC) load using Oracle Automatic Storage Management (ASM).\n         You can specify an integer value between 1000 (the default) and 200,000 (the\n         maximum).</p>"}))
    OracleSettings.add_member(:access_alternate_directly, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AccessAlternateDirectly', traits: {"smithy.api#documentation" => "<p>Set this attribute to <code>false</code> in order to use the Binary Reader to capture\n         change data for an Amazon RDS for Oracle as the source. This tells the DMS instance to not\n         access redo logs through any specified path prefix replacement using direct file\n         access.</p>"}))
    OracleSettings.add_member(:use_alternate_folder_for_online, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseAlternateFolderForOnline', traits: {"smithy.api#documentation" => "<p>Set this attribute to <code>true</code> in order to use the Binary Reader to capture\n         change data for an Amazon RDS for Oracle as the source. This tells the DMS instance to use any\n         specified prefix replacement to access all online redo logs.</p>"}))
    OracleSettings.add_member(:oracle_path_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OraclePathPrefix', traits: {"smithy.api#documentation" => "<p>Set this string attribute to the required value in order to use the Binary Reader to\n         capture change data for an Amazon RDS for Oracle as the source. This value specifies the\n         default Oracle root used to access the redo logs.</p>"}))
    OracleSettings.add_member(:use_path_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'UsePathPrefix', traits: {"smithy.api#documentation" => "<p>Set this string attribute to the required value in order to use the Binary Reader to\n         capture change data for an Amazon RDS for Oracle as the source. This value specifies the\n         path prefix used to replace the default Oracle root to access the redo logs.</p>"}))
    OracleSettings.add_member(:replace_path_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ReplacePathPrefix', traits: {"smithy.api#documentation" => "<p>Set this attribute to true in order to use the Binary Reader to capture change data for\n         an Amazon RDS for Oracle as the source. This setting tells DMS instance to replace the default\n         Oracle root with the specified <code>usePathPrefix</code> setting to access the redo\n         logs.</p>"}))
    OracleSettings.add_member(:enable_homogenous_tablespace, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableHomogenousTablespace', traits: {"smithy.api#documentation" => "<p>Set this attribute to enable homogenous tablespace replication and create existing\n         tables or indexes under the same tablespace on the target.</p>"}))
    OracleSettings.add_member(:direct_path_no_log, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DirectPathNoLog', traits: {"smithy.api#documentation" => "<p>When set to <code>true</code>, this attribute helps to increase the commit rate on the\n         Oracle target database by writing directly to tables and not writing a trail to database\n         logs.</p>"}))
    OracleSettings.add_member(:archived_logs_only, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ArchivedLogsOnly', traits: {"smithy.api#documentation" => "<p>When this field is set to <code>True</code>, DMS only accesses the archived redo logs.\n         If the archived redo logs are stored on Automatic Storage Management (ASM) only, the DMS\n         user account needs to be granted ASM privileges.</p>"}))
    OracleSettings.add_member(:asm_password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'AsmPassword', traits: {"smithy.api#documentation" => "<p>For an Oracle source endpoint, your Oracle Automatic Storage Management (ASM) password.\n         You can set this value from the <code>\n               <i>asm_user_password</i>\n            </code> value.\n         You set this value as part of the comma-separated value that you set to the\n            <code>Password</code> request parameter when you create the endpoint to access\n         transaction logs using Binary Reader. For more information, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.Oracle.html#dms/latest/userguide/CHAP_Source.Oracle.html#CHAP_Source.Oracle.CDC.Configuration\">Configuration for change data capture (CDC) on an Oracle source\n            database</a>.</p>"}))
    OracleSettings.add_member(:asm_server, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AsmServer', traits: {"smithy.api#documentation" => "<p>For an Oracle source endpoint, your ASM server address. You can set this value from the\n            <code>asm_server</code> value. You set <code>asm_server</code> as part of the extra\n         connection attribute string to access an Oracle server with Binary Reader that uses ASM.\n         For more information, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.Oracle.html#dms/latest/userguide/CHAP_Source.Oracle.html#CHAP_Source.Oracle.CDC.Configuration\">Configuration for change data capture (CDC) on an Oracle source\n            database</a>.</p>"}))
    OracleSettings.add_member(:asm_user, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AsmUser', traits: {"smithy.api#documentation" => "<p>For an Oracle source endpoint, your ASM user name. You can set this value from the\n            <code>asm_user</code> value. You set <code>asm_user</code> as part of the extra\n         connection attribute string to access an Oracle server with Binary Reader that uses ASM.\n         For more information, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.Oracle.html#dms/latest/userguide/CHAP_Source.Oracle.html#CHAP_Source.Oracle.CDC.Configuration\">Configuration for change data capture (CDC) on an Oracle source\n            database</a>.</p>"}))
    OracleSettings.add_member(:char_length_semantics, Smithy::Schema::Shapes::ShapeRef.new(shape: CharLengthSemantics, location_name: 'CharLengthSemantics', traits: {"smithy.api#documentation" => "<p>Specifies whether the length of a character column is in bytes or in characters. To\n         indicate that the character column length is in characters, set this attribute to\n            <code>CHAR</code>. Otherwise, the character column length is in bytes.</p>\n         <p>Example: <code>charLengthSemantics=CHAR;</code>\n         </p>"}))
    OracleSettings.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>Database name for the endpoint.</p>"}))
    OracleSettings.add_member(:direct_path_parallel_load, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DirectPathParallelLoad', traits: {"smithy.api#documentation" => "<p>When set to <code>true</code>, this attribute specifies a parallel load when\n            <code>useDirectPathFullLoad</code> is set to <code>Y</code>. This attribute also only\n         applies when you use the DMS parallel load feature. Note that the target table cannot\n         have any constraints or indexes.</p>"}))
    OracleSettings.add_member(:fail_tasks_on_lob_truncation, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'FailTasksOnLobTruncation', traits: {"smithy.api#documentation" => "<p>When set to <code>true</code>, this attribute causes a task to fail if the actual size\n         of an LOB column is greater than the specified <code>LobMaxSize</code>.</p>\n         <p>If a task is set to limited LOB mode and this option is set to <code>true</code>, the\n         task fails instead of truncating the LOB data.</p>"}))
    OracleSettings.add_member(:number_datatype_scale, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'NumberDatatypeScale', traits: {"smithy.api#documentation" => "<p>Specifies the number scale. You can select a scale up to 38, or you can select FLOAT. By\n         default, the NUMBER data type is converted to precision 38, scale 10.</p>\n         <p>Example: <code>numberDataTypeScale=12</code>\n         </p>"}))
    OracleSettings.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>Endpoint connection password.</p>"}))
    OracleSettings.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>Endpoint TCP port.</p>"}))
    OracleSettings.add_member(:read_table_space_name, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ReadTableSpaceName', traits: {"smithy.api#documentation" => "<p>When set to <code>true</code>, this attribute supports tablespace replication.</p>"}))
    OracleSettings.add_member(:retry_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'RetryInterval', traits: {"smithy.api#documentation" => "<p>Specifies the number of seconds that the system waits before resending a query.</p>\n         <p>Example: <code>retryInterval=6;</code>\n         </p>"}))
    OracleSettings.add_member(:security_db_encryption, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'SecurityDbEncryption', traits: {"smithy.api#documentation" => "<p>For an Oracle source endpoint, the transparent data encryption (TDE) password required\n         by AWM DMS to access Oracle redo logs encrypted by TDE using Binary Reader. It is also the\n               <code>\n               <i>TDE_Password</i>\n            </code> part of the comma-separated value you\n         set to the <code>Password</code> request parameter when you create the endpoint. The\n            <code>SecurityDbEncryptian</code> setting is related to this\n            <code>SecurityDbEncryptionName</code> setting. For more information, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.Oracle.html#CHAP_Source.Oracle.Encryption\"> Supported encryption methods for using Oracle as a source for\n            DMS </a> in the <i>Database Migration Service User Guide</i>. </p>"}))
    OracleSettings.add_member(:security_db_encryption_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecurityDbEncryptionName', traits: {"smithy.api#documentation" => "<p>For an Oracle source endpoint, the name of a key used for the transparent data\n         encryption (TDE) of the columns and tablespaces in an Oracle source database that is\n         encrypted using TDE. The key value is the value of the <code>SecurityDbEncryption</code>\n         setting. For more information on setting the key name value of\n            <code>SecurityDbEncryptionName</code>, see the information and example for setting the\n            <code>securityDbEncryptionName</code> extra connection attribute in <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.Oracle.html#CHAP_Source.Oracle.Encryption\"> Supported encryption methods for using Oracle as a source for\n            DMS </a> in the <i>Database Migration Service User Guide</i>.</p>"}))
    OracleSettings.add_member(:server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerName', traits: {"smithy.api#documentation" => "<p>Fully qualified domain name of the endpoint.</p>\n         <p>For an Amazon RDS Oracle instance, this is the output of <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_DescribeDBInstances.html\">DescribeDBInstances</a>, in the <code>\n               <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_Endpoint.html\">Endpoint</a>.Address</code> field.</p>"}))
    OracleSettings.add_member(:spatial_data_option_to_geo_json_function_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SpatialDataOptionToGeoJsonFunctionName', traits: {"smithy.api#documentation" => "<p>Use this attribute to convert <code>SDO_GEOMETRY</code> to <code>GEOJSON</code> format.\n         By default, DMS calls the <code>SDO2GEOJSON</code> custom function if present and\n         accessible. Or you can create your own custom function that mimics the operation of\n            <code>SDOGEOJSON</code> and set <code>SpatialDataOptionToGeoJsonFunctionName</code> to\n         call it instead. </p>"}))
    OracleSettings.add_member(:standby_delay_time, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'StandbyDelayTime', traits: {"smithy.api#documentation" => "<p>Use this attribute to specify a time in minutes for the delay in standby sync. If the\n         source is an Oracle Active Data Guard standby database, use this attribute to specify the\n         time lag between primary and standby databases.</p>\n         <p>In DMS, you can create an Oracle CDC task that uses an Active Data Guard standby\n         instance as a source for replicating ongoing changes. Doing this eliminates the need to\n         connect to an active database that might be in production.</p>"}))
    OracleSettings.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>Endpoint connection user name.</p>"}))
    OracleSettings.add_member(:use_b_file, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseBFile', traits: {"smithy.api#documentation" => "<p>Set this attribute to True to capture change data using the Binary Reader utility. Set\n            <code>UseLogminerReader</code> to False to set this attribute to True. To use Binary\n         Reader with Amazon RDS for Oracle as the source, you set additional attributes. For more\n         information about using this setting with Oracle Automatic Storage Management (ASM), see\n            <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.Oracle.html#CHAP_Source.Oracle.CDC\"> Using Oracle LogMiner or DMS Binary Reader for\n         CDC</a>.</p>"}))
    OracleSettings.add_member(:use_direct_path_full_load, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseDirectPathFullLoad', traits: {"smithy.api#documentation" => "<p>Set this attribute to True to have DMS use a direct path full load. Specify this value\n         to use the direct path protocol in the Oracle Call Interface (OCI). By using this OCI\n         protocol, you can bulk-load Oracle target tables during a full load.</p>"}))
    OracleSettings.add_member(:use_logminer_reader, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseLogminerReader', traits: {"smithy.api#documentation" => "<p>Set this attribute to True to capture change data using the Oracle LogMiner utility (the\n         default). Set this attribute to False if you want to access the redo logs as a binary file.\n         When you set <code>UseLogminerReader</code> to False, also set <code>UseBfile</code> to\n         True. For more information on this setting and using Oracle ASM, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Source.Oracle.html#CHAP_Source.Oracle.CDC\"> Using Oracle LogMiner or DMS Binary Reader for CDC</a> in\n         the <i>DMS User Guide</i>.</p>"}))
    OracleSettings.add_member(:secrets_manager_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The full Amazon Resource Name (ARN) of the IAM role that specifies DMS as the trusted\n         entity and grants the required permissions to access the value in\n            <code>SecretsManagerSecret</code>. The role must allow the <code>iam:PassRole</code>\n         action. <code>SecretsManagerSecret</code> has the value of the Amazon Web Services Secrets Manager secret that\n         allows access to the Oracle endpoint.</p>\n         <note>\n            <p>You can specify one of two sets of values for these permissions. You can specify the\n            values for this setting and <code>SecretsManagerSecretId</code>. Or you can specify\n            clear-text values for <code>UserName</code>, <code>Password</code>,\n               <code>ServerName</code>, and <code>Port</code>. You can't specify both. For more\n            information on creating this <code>SecretsManagerSecret</code> and the\n               <code>SecretsManagerAccessRoleArn</code> and <code>SecretsManagerSecretId</code>\n            required to access it, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Security.html#security-iam-secretsmanager\">Using secrets to access Database Migration Service resources</a> in the\n               <i>Database Migration Service User Guide</i>.</p>\n         </note>"}))
    OracleSettings.add_member(:secrets_manager_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerSecretId', traits: {"smithy.api#documentation" => "<p>The full ARN, partial ARN, or friendly name of the <code>SecretsManagerSecret</code>\n         that contains the Oracle endpoint connection details.</p>"}))
    OracleSettings.add_member(:secrets_manager_oracle_asm_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerOracleAsmAccessRoleArn', traits: {"smithy.api#documentation" => "<p>Required only if your Oracle endpoint uses Automatic Storage Management (ASM). The full\n         ARN of the IAM role that specifies DMS as the trusted entity and grants the required\n         permissions to access the <code>SecretsManagerOracleAsmSecret</code>. This\n            <code>SecretsManagerOracleAsmSecret</code> has the secret value that allows access to\n         the Oracle ASM of the endpoint.</p>\n         <note>\n            <p>You can specify one of two sets of values for these permissions. You can specify the\n            values for this setting and <code>SecretsManagerOracleAsmSecretId</code>. Or you can\n            specify clear-text values for <code>AsmUser</code>, <code>AsmPassword</code>, and\n               <code>AsmServerName</code>. You can't specify both. For more information on\n            creating this <code>SecretsManagerOracleAsmSecret</code> and the\n               <code>SecretsManagerOracleAsmAccessRoleArn</code> and\n               <code>SecretsManagerOracleAsmSecretId</code> required to access it, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Security.html#security-iam-secretsmanager\">Using secrets to access Database Migration Service resources</a> in the\n               <i>Database Migration Service User Guide</i>.</p>\n         </note>"}))
    OracleSettings.add_member(:secrets_manager_oracle_asm_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerOracleAsmSecretId', traits: {"smithy.api#documentation" => "<p>Required only if your Oracle endpoint uses Automatic Storage Management (ASM). The full\n         ARN, partial ARN, or friendly name of the <code>SecretsManagerOracleAsmSecret</code> that\n         contains the Oracle ASM connection details for the Oracle endpoint.</p>"}))
    OracleSettings.add_member(:trim_space_in_char, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'TrimSpaceInChar', traits: {"smithy.api#documentation" => "<p>Use the <code>TrimSpaceInChar</code> source endpoint setting to trim data on CHAR and\n         NCHAR data types during migration. The default value is <code>true</code>.</p>"}))
    OracleSettings.add_member(:convert_timestamp_with_zone_to_utc, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ConvertTimestampWithZoneToUTC', traits: {"smithy.api#documentation" => "<p>When true, converts timestamps with the <code>timezone</code> datatype to their UTC\n         value.</p>"}))
    OracleSettings.add_member(:open_transaction_window, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'OpenTransactionWindow', traits: {"smithy.api#documentation" => "<p>The timeframe in minutes to check for open transactions for a CDC-only task.</p>\n         <p>You can specify an integer value between 0 (the default) and 240 (the maximum). </p>\n         <note>\n            <p>This parameter is only valid in DMS version 3.5.0 and later.</p>\n         </note>"}))
    OracleSettings.add_member(:authentication_method, Smithy::Schema::Shapes::ShapeRef.new(shape: OracleAuthenticationMethod, location_name: 'AuthenticationMethod', traits: {"smithy.api#documentation" => "<p>Specifies the authentication method to be used with Oracle.</p>"}))
    OracleSettings.type = Types::OracleSettings
    OrderableReplicationInstance.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version of the replication engine.</p>"}))
    OrderableReplicationInstance.add_member(:replication_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: ReplicationInstanceClass, location_name: 'ReplicationInstanceClass', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of the replication instance as defined for the specified\n         replication instance class. For example to specify the instance class dms.c4.large, set\n         this parameter to <code>\"dms.c4.large\"</code>.</p>\n         <p>For more information on the settings and capacities for the available replication\n         instance classes, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_ReplicationInstance.html#CHAP_ReplicationInstance.InDepth\"> Selecting the right DMS replication instance for your\n            migration</a>. </p>"}))
    OrderableReplicationInstance.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The type of storage used by the replication instance.</p>"}))
    OrderableReplicationInstance.add_member(:min_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MinAllocatedStorage', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The minimum amount of storage (in gigabytes) that can be allocated for the replication\n         instance.</p>"}))
    OrderableReplicationInstance.add_member(:max_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MaxAllocatedStorage', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The minimum amount of storage (in gigabytes) that can be allocated for the replication\n         instance.</p>"}))
    OrderableReplicationInstance.add_member(:default_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'DefaultAllocatedStorage', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The default amount of storage (in gigabytes) that is allocated for the replication\n         instance.</p>"}))
    OrderableReplicationInstance.add_member(:included_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'IncludedAllocatedStorage', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The amount of storage (in gigabytes) that is allocated for the replication\n         instance.</p>"}))
    OrderableReplicationInstance.add_member(:availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZonesList, location_name: 'AvailabilityZones', traits: {"smithy.api#documentation" => "<p>List of Availability Zones for this replication instance.</p>"}))
    OrderableReplicationInstance.add_member(:release_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ReleaseStatusValues, location_name: 'ReleaseStatus', traits: {"smithy.api#documentation" => "<p>The value returned when the specified <code>EngineVersion</code> of the replication\n         instance is in Beta or test mode. This indicates some features might not work as\n         expected.</p>\n         <note>\n            <p>DMS supports the <code>ReleaseStatus</code> parameter in versions 3.1.4 and\n            later.</p>\n         </note>"}))
    OrderableReplicationInstance.type = Types::OrderableReplicationInstance
    OrderableReplicationInstanceList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: OrderableReplicationInstance, traits: {"smithy.api#xmlName" => "OrderableReplicationInstance"})
    OriginTypeValue.add_member(:source, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SOURCE', traits: {"smithy.api#enumValue" => "SOURCE"}))
    OriginTypeValue.add_member(:target, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TARGET', traits: {"smithy.api#enumValue" => "TARGET"}))
    ParquetVersionValue.add_member(:parquet_1_0, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PARQUET_1_0', traits: {"smithy.api#enumValue" => "parquet-1-0"}))
    ParquetVersionValue.add_member(:parquet_2_0, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PARQUET_2_0', traits: {"smithy.api#enumValue" => "parquet-2-0"}))
    PendingMaintenanceAction.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>The type of pending maintenance action that is available for the resource.</p>"}))
    PendingMaintenanceAction.add_member(:auto_applied_after_date, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'AutoAppliedAfterDate', traits: {"smithy.api#documentation" => "<p>The date of the maintenance window when the action is to be applied. The maintenance\n         action is applied to the resource during its first maintenance window after this date. If\n         this date is specified, any <code>next-maintenance</code> opt-in requests are\n         ignored.</p>"}))
    PendingMaintenanceAction.add_member(:forced_apply_date, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'ForcedApplyDate', traits: {"smithy.api#documentation" => "<p>The date when the maintenance action will be automatically applied. The maintenance\n         action is applied to the resource on this date regardless of the maintenance window for the\n         resource. If this date is specified, any <code>immediate</code> opt-in requests are\n         ignored.</p>"}))
    PendingMaintenanceAction.add_member(:opt_in_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptInStatus', traits: {"smithy.api#documentation" => "<p>The type of opt-in request that has been received for the resource.</p>"}))
    PendingMaintenanceAction.add_member(:current_apply_date, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'CurrentApplyDate', traits: {"smithy.api#documentation" => "<p>The effective date when the pending maintenance action will be applied to the resource.\n         This date takes into account opt-in requests received from the\n            <code>ApplyPendingMaintenanceAction</code> API operation, and also the\n            <code>AutoAppliedAfterDate</code> and <code>ForcedApplyDate</code> parameter values.\n         This value is blank if an opt-in request has not been received and nothing has been\n         specified for <code>AutoAppliedAfterDate</code> or <code>ForcedApplyDate</code>.</p>"}))
    PendingMaintenanceAction.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description providing more detail about the maintenance action.</p>"}))
    PendingMaintenanceAction.type = Types::PendingMaintenanceAction
    PendingMaintenanceActionDetails.member = Smithy::Schema::Shapes::ShapeRef.new(shape: PendingMaintenanceAction, traits: {"smithy.api#xmlName" => "PendingMaintenanceAction"})
    PendingMaintenanceActions.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ResourcePendingMaintenanceActions, traits: {"smithy.api#xmlName" => "ResourcePendingMaintenanceActions"})
    PluginNameValue.add_member(:no_preference, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NO_PREFERENCE', traits: {"smithy.api#enumValue" => "no-preference"}))
    PluginNameValue.add_member(:test_decoding, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TEST_DECODING', traits: {"smithy.api#enumValue" => "test-decoding"}))
    PluginNameValue.add_member(:pglogical, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PGLOGICAL', traits: {"smithy.api#enumValue" => "pglogical"}))
    PostgreSQLAuthenticationMethod.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Password', traits: {"smithy.api#enumValue" => "password"}))
    PostgreSQLAuthenticationMethod.add_member(:iam, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'IAM', traits: {"smithy.api#enumValue" => "iam"}))
    PostgreSQLSettings.add_member(:after_connect_script, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AfterConnectScript', traits: {"smithy.api#documentation" => "<p>For use with change data capture (CDC) only, this attribute has DMS bypass foreign\n         keys and user triggers to reduce the time it takes to bulk load data.</p>\n         <p>Example: <code>afterConnectScript=SET session_replication_role='replica'</code>\n         </p>"}))
    PostgreSQLSettings.add_member(:capture_ddls, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CaptureDdls', traits: {"smithy.api#documentation" => "<p>To capture DDL events, DMS creates various artifacts in the PostgreSQL database when\n         the task starts. You can later remove these artifacts.</p>\n         <p>The default value is <code>true</code>.</p>\n         <p>If this value is set to <code>N</code>, you don't have to create tables or triggers on\n         the source database.</p>"}))
    PostgreSQLSettings.add_member(:max_file_size, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxFileSize', traits: {"smithy.api#documentation" => "<p>Specifies the maximum size (in KB) of any .csv file used to transfer data to\n         PostgreSQL.</p>\n         <p>The default value is 32,768 KB (32 MB).</p>\n         <p>Example: <code>maxFileSize=512</code>\n         </p>"}))
    PostgreSQLSettings.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>Database name for the endpoint.</p>"}))
    PostgreSQLSettings.add_member(:ddl_artifacts_schema, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DdlArtifactsSchema', traits: {"smithy.api#documentation" => "<p>The schema in which the operational DDL database artifacts are created.</p>\n         <p>The default value is <code>public</code>.</p>\n         <p>Example: <code>ddlArtifactsSchema=xyzddlschema;</code>\n         </p>"}))
    PostgreSQLSettings.add_member(:execute_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ExecuteTimeout', traits: {"smithy.api#documentation" => "<p>Sets the client statement timeout for the PostgreSQL instance, in seconds. The default\n         value is 60 seconds.</p>\n         <p>Example: <code>executeTimeout=100;</code>\n         </p>"}))
    PostgreSQLSettings.add_member(:fail_tasks_on_lob_truncation, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'FailTasksOnLobTruncation', traits: {"smithy.api#documentation" => "<p>When set to <code>true</code>, this value causes a task to fail if the actual size of a\n         LOB column is greater than the specified <code>LobMaxSize</code>.</p>\n         <p>The default value is <code>false</code>.</p>\n         <p>If task is set to Limited LOB mode and this option is set to true, the task fails\n         instead of truncating the LOB data.</p>"}))
    PostgreSQLSettings.add_member(:heartbeat_enable, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'HeartbeatEnable', traits: {"smithy.api#documentation" => "<p>The write-ahead log (WAL) heartbeat feature mimics a dummy transaction. By doing this,\n         it prevents idle logical replication slots from holding onto old WAL logs, which can result\n         in storage full situations on the source. This heartbeat keeps <code>restart_lsn</code>\n         moving and prevents storage full scenarios.</p>\n         <p>The default value is <code>false</code>.</p>"}))
    PostgreSQLSettings.add_member(:heartbeat_schema, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'HeartbeatSchema', traits: {"smithy.api#documentation" => "<p>Sets the schema in which the heartbeat artifacts are created.</p>\n         <p>The default value is <code>public</code>.</p>"}))
    PostgreSQLSettings.add_member(:heartbeat_frequency, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'HeartbeatFrequency', traits: {"smithy.api#documentation" => "<p>Sets the WAL heartbeat frequency (in minutes).</p>\n         <p>The default value is 5 minutes.</p>"}))
    PostgreSQLSettings.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>Endpoint connection password.</p>"}))
    PostgreSQLSettings.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>Endpoint TCP port. The default is 5432.</p>"}))
    PostgreSQLSettings.add_member(:server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerName', traits: {"smithy.api#documentation" => "<p>The host name of the endpoint database. </p>\n         <p>For an Amazon RDS PostgreSQL instance, this is the output of <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_DescribeDBInstances.html\">DescribeDBInstances</a>, in the <code>\n               <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_Endpoint.html\">Endpoint</a>.Address</code> field.</p>\n         <p>For an Aurora PostgreSQL instance, this is the output of <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_DescribeDBClusters.html\">DescribeDBClusters</a>, in the <code>Endpoint</code> field.</p>"}))
    PostgreSQLSettings.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>Endpoint connection user name.</p>"}))
    PostgreSQLSettings.add_member(:slot_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SlotName', traits: {"smithy.api#documentation" => "<p>Sets the name of a previously created logical replication slot for a change data capture\n         (CDC) load of the PostgreSQL source instance. </p>\n         <p>When used with the <code>CdcStartPosition</code> request parameter for the DMS API ,\n         this attribute also makes it possible to use native CDC start points. DMS verifies that the\n         specified logical replication slot exists before starting the CDC load task. It also\n         verifies that the task was created with a valid setting of <code>CdcStartPosition</code>.\n         If the specified slot doesn't exist or the task doesn't have a valid\n            <code>CdcStartPosition</code> setting, DMS raises an error.</p>\n         <p>For more information about setting the <code>CdcStartPosition</code> request parameter,\n         see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Task.CDC.html#CHAP_Task.CDC.StartPoint.Native\">Determining a CDC native start point</a> in the <i>Database Migration Service User\n            Guide</i>. For more information about using <code>CdcStartPosition</code>, see\n            <a href=\"https://docs.aws.amazon.com/dms/latest/APIReference/API_CreateReplicationTask.html\">CreateReplicationTask</a>, <a href=\"https://docs.aws.amazon.com/dms/latest/APIReference/API_StartReplicationTask.html\">StartReplicationTask</a>, and <a href=\"https://docs.aws.amazon.com/dms/latest/APIReference/API_ModifyReplicationTask.html\">ModifyReplicationTask</a>.</p>"}))
    PostgreSQLSettings.add_member(:plugin_name, Smithy::Schema::Shapes::ShapeRef.new(shape: PluginNameValue, location_name: 'PluginName', traits: {"smithy.api#documentation" => "<p>Specifies the plugin to use to create a replication slot.</p>\n         <p>The default value is <code>pglogical</code>.</p>"}))
    PostgreSQLSettings.add_member(:secrets_manager_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The full Amazon Resource Name (ARN) of the IAM role that specifies DMS as the trusted\n         entity and grants the required permissions to access the value in\n            <code>SecretsManagerSecret</code>. The role must allow the <code>iam:PassRole</code>\n         action. <code>SecretsManagerSecret</code> has the value of the Amazon Web Services Secrets Manager secret that\n         allows access to the PostgreSQL endpoint.</p>\n         <note>\n            <p>You can specify one of two sets of values for these permissions. You can specify the\n            values for this setting and <code>SecretsManagerSecretId</code>. Or you can specify\n            clear-text values for <code>UserName</code>, <code>Password</code>,\n               <code>ServerName</code>, and <code>Port</code>. You can't specify both. For more\n            information on creating this <code>SecretsManagerSecret</code> and the\n               <code>SecretsManagerAccessRoleArn</code> and <code>SecretsManagerSecretId</code>\n            required to access it, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Security.html#security-iam-secretsmanager\">Using secrets to access Database Migration Service resources</a> in the\n               <i>Database Migration Service User Guide</i>.</p>\n         </note>"}))
    PostgreSQLSettings.add_member(:secrets_manager_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerSecretId', traits: {"smithy.api#documentation" => "<p>The full ARN, partial ARN, or friendly name of the <code>SecretsManagerSecret</code>\n         that contains the PostgreSQL endpoint connection details.</p>"}))
    PostgreSQLSettings.add_member(:trim_space_in_char, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'TrimSpaceInChar', traits: {"smithy.api#documentation" => "<p>Use the <code>TrimSpaceInChar</code> source endpoint setting to trim data on CHAR and\n         NCHAR data types during migration. The default value is <code>true</code>.</p>"}))
    PostgreSQLSettings.add_member(:map_boolean_as_boolean, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MapBooleanAsBoolean', traits: {"smithy.api#documentation" => "<p>When true, lets PostgreSQL migrate the boolean type as boolean. By default, PostgreSQL\n         migrates booleans as <code>varchar(5)</code>. You must set this setting on both the source\n         and target endpoints for it to take effect.</p>\n         <p>The default value is <code>false</code>.</p>"}))
    PostgreSQLSettings.add_member(:map_jsonb_as_clob, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MapJsonbAsClob', traits: {"smithy.api#documentation" => "<p>When true, DMS migrates JSONB values as CLOB.</p>\n         <p>The default value is <code>false</code>.</p>"}))
    PostgreSQLSettings.add_member(:map_long_varchar_as, Smithy::Schema::Shapes::ShapeRef.new(shape: LongVarcharMappingType, location_name: 'MapLongVarcharAs', traits: {"smithy.api#documentation" => "<p>Sets what datatype to map LONG values as.</p>\n         <p>The default value is <code>wstring</code>.</p>"}))
    PostgreSQLSettings.add_member(:database_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseMode, location_name: 'DatabaseMode', traits: {"smithy.api#documentation" => "<p>Specifies the default behavior of the replication's handling of PostgreSQL- compatible\n         endpoints that require some additional configuration, such as Babelfish endpoints.</p>"}))
    PostgreSQLSettings.add_member(:babelfish_database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BabelfishDatabaseName', traits: {"smithy.api#documentation" => "<p>The Babelfish for Aurora PostgreSQL database name for the endpoint.</p>"}))
    PostgreSQLSettings.add_member(:disable_unicode_source_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DisableUnicodeSourceFilter', traits: {"smithy.api#documentation" => "<p>Disables the Unicode source filter with PostgreSQL, for values passed into the Selection\n         rule filter on Source Endpoint column values. By default DMS performs source filter\n         comparisons using a Unicode string which can cause look ups to ignore the indexes in the\n         text columns and slow down migrations.</p>\n         <p>Unicode support should only be disabled when using a selection rule filter is on a text\n         column in the Source database that is indexed.</p>"}))
    PostgreSQLSettings.add_member(:service_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServiceAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The IAM role arn you can use to authenticate the connection to your endpoint. Ensure to include <code>iam:PassRole</code> and <code>rds-db:connect</code> actions in permission policy.</p>"}))
