    RedshiftSettings.add_member(:accept_any_date, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AcceptAnyDate', traits: {"smithy.api#documentation" => "<p>A value that indicates to allow any date format, including invalid formats such as\n         00/00/00 00:00:00, to be loaded without generating an error. You can choose\n            <code>true</code> or <code>false</code> (the default).</p>\n         <p>This parameter applies only to TIMESTAMP and DATE columns. Always use ACCEPTANYDATE with\n         the DATEFORMAT parameter. If the date format for the data doesn't match the DATEFORMAT\n         specification, Amazon Redshift inserts a NULL value into that field. </p>"}))
    RedshiftSettings.add_member(:after_connect_script, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AfterConnectScript', traits: {"smithy.api#documentation" => "<p>Code to run after connecting. This parameter should contain the code itself, not the\n         name of a file containing the code.</p>"}))
    RedshiftSettings.add_member(:bucket_folder, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BucketFolder', traits: {"smithy.api#documentation" => "<p>An S3 folder where the comma-separated-value (.csv) files are stored before being\n         uploaded to the target Redshift cluster. </p>\n         <p>For full load mode, DMS converts source records into .csv files and loads them to the\n            <i>BucketFolder/TableID</i> path. DMS uses the Redshift\n            <code>COPY</code> command to upload the .csv files to the target table. The files are\n         deleted once the <code>COPY</code> operation has finished. For more information, see <a href=\"https://docs.aws.amazon.com/redshift/latest/dg/r_COPY.html\">COPY</a> in the\n            <i>Amazon Redshift Database Developer Guide</i>.</p>\n         <p>For change-data-capture (CDC) mode, DMS creates a <i>NetChanges</i>\n         table, and loads the .csv files to this <i>BucketFolder/NetChangesTableID</i>\n         path.</p>"}))
    RedshiftSettings.add_member(:bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BucketName', traits: {"smithy.api#documentation" => "<p>The name of the intermediate S3 bucket used to store .csv files before uploading data to\n         Redshift.</p>"}))
    RedshiftSettings.add_member(:case_sensitive_names, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CaseSensitiveNames', traits: {"smithy.api#documentation" => "<p>If Amazon Redshift is configured to support case sensitive schema names, set\n            <code>CaseSensitiveNames</code> to <code>true</code>. The default is\n         <code>false</code>.</p>"}))
    RedshiftSettings.add_member(:comp_update, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CompUpdate', traits: {"smithy.api#documentation" => "<p>If you set <code>CompUpdate</code> to <code>true</code> Amazon Redshift applies\n         automatic compression if the table is empty. This applies even if the table columns already\n         have encodings other than <code>RAW</code>. If you set <code>CompUpdate</code> to\n            <code>false</code>, automatic compression is disabled and existing column encodings\n         aren't changed. The default is <code>true</code>.</p>"}))
    RedshiftSettings.add_member(:connection_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ConnectionTimeout', traits: {"smithy.api#documentation" => "<p>A value that sets the amount of time to wait (in milliseconds) before timing out,\n         beginning from when you initially establish a connection.</p>"}))
    RedshiftSettings.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon Redshift data warehouse (service) that you are working\n         with.</p>"}))
    RedshiftSettings.add_member(:date_format, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DateFormat', traits: {"smithy.api#documentation" => "<p>The date format that you are using. Valid values are <code>auto</code> (case-sensitive),\n         your date format string enclosed in quotes, or NULL. If this parameter is left unset\n         (NULL), it defaults to a format of 'YYYY-MM-DD'. Using <code>auto</code> recognizes most\n         strings, even some that aren't supported when you use a date format string. </p>\n         <p>If your date and time values use formats different from each other, set this to\n            <code>auto</code>. </p>"}))
    RedshiftSettings.add_member(:empty_as_null, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EmptyAsNull', traits: {"smithy.api#documentation" => "<p>A value that specifies whether DMS should migrate empty CHAR and VARCHAR fields as\n         NULL. A value of <code>true</code> sets empty CHAR and VARCHAR fields to null. The default\n         is <code>false</code>.</p>"}))
    RedshiftSettings.add_member(:encryption_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionModeValue, location_name: 'EncryptionMode', traits: {"smithy.api#documentation" => "<p>The type of server-side encryption that you want to use for your data. This encryption\n         type is part of the endpoint settings or the extra connections attributes for Amazon S3.\n         You can choose either <code>SSE_S3</code> (the default) or <code>SSE_KMS</code>. </p>\n         <note>\n            <p>For the <code>ModifyEndpoint</code> operation, you can change the existing value of\n            the <code>EncryptionMode</code> parameter from <code>SSE_KMS</code> to\n               <code>SSE_S3</code>. But you can’t change the existing value from <code>SSE_S3</code>\n            to <code>SSE_KMS</code>.</p>\n         </note>\n         <p>To use <code>SSE_S3</code>, create an Identity and Access Management (IAM) role with a policy that allows\n            <code>\"arn:aws:s3:::*\"</code> to use the following actions: <code>\"s3:PutObject\",\n            \"s3:ListBucket\"</code>\n         </p>"}))
    RedshiftSettings.add_member(:explicit_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ExplicitIds', traits: {"smithy.api#documentation" => "<p>This setting is only valid for a full-load migration task. Set <code>ExplicitIds</code>\n         to <code>true</code> to have tables with <code>IDENTITY</code> columns override their\n         auto-generated values with explicit values loaded from the source data files used to\n         populate the tables. The default is <code>false</code>.</p>"}))
    RedshiftSettings.add_member(:file_transfer_upload_streams, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'FileTransferUploadStreams', traits: {"smithy.api#documentation" => "<p>The number of threads used to upload a single file. This parameter accepts a value from\n         1 through 64. It defaults to 10.</p>\n         <p>The number of parallel streams used to upload a single .csv file to an S3 bucket using\n         S3 Multipart Upload. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/mpuoverview.html\">Multipart upload\n            overview</a>. </p>\n         <p>\n            <code>FileTransferUploadStreams</code> accepts a value from 1 through 64. It defaults to\n         10.</p>"}))
    RedshiftSettings.add_member(:load_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'LoadTimeout', traits: {"smithy.api#documentation" => "<p>The amount of time to wait (in milliseconds) before timing out of operations performed\n         by DMS on a Redshift cluster, such as Redshift COPY, INSERT, DELETE, and UPDATE.</p>"}))
    RedshiftSettings.add_member(:max_file_size, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxFileSize', traits: {"smithy.api#documentation" => "<p>The maximum size (in KB) of any .csv file used to load data on an S3 bucket and transfer\n         data to Amazon Redshift. It defaults to 1048576KB (1 GB).</p>"}))
    RedshiftSettings.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretString, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>The password for the user named in the <code>username</code> property.</p>"}))
    RedshiftSettings.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number for Amazon Redshift. The default value is 5439.</p>"}))
    RedshiftSettings.add_member(:remove_quotes, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'RemoveQuotes', traits: {"smithy.api#documentation" => "<p>A value that specifies to remove surrounding quotation marks from strings in the\n         incoming data. All characters within the quotation marks, including delimiters, are\n         retained. Choose <code>true</code> to remove quotation marks. The default is\n            <code>false</code>.</p>"}))
    RedshiftSettings.add_member(:replace_invalid_chars, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplaceInvalidChars', traits: {"smithy.api#documentation" => "<p>A list of characters that you want to replace. Use with\n         <code>ReplaceChars</code>.</p>"}))
    RedshiftSettings.add_member(:replace_chars, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplaceChars', traits: {"smithy.api#documentation" => "<p>A value that specifies to replaces the invalid characters specified in\n            <code>ReplaceInvalidChars</code>, substituting the specified characters instead. The\n         default is <code>\"?\"</code>.</p>"}))
    RedshiftSettings.add_member(:server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon Redshift cluster you are using.</p>"}))
    RedshiftSettings.add_member(:service_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServiceAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM role that has access to the Amazon Redshift\n         service. The role must allow the <code>iam:PassRole</code> action.</p>"}))
    RedshiftSettings.add_member(:server_side_encryption_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerSideEncryptionKmsKeyId', traits: {"smithy.api#documentation" => "<p>The KMS key ID. If you are using <code>SSE_KMS</code> for the\n            <code>EncryptionMode</code>, provide this key ID. The key that you use needs an attached\n         policy that enables IAM user permissions and allows use of the key.</p>"}))
    RedshiftSettings.add_member(:time_format, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TimeFormat', traits: {"smithy.api#documentation" => "<p>The time format that you want to use. Valid values are <code>auto</code>\n         (case-sensitive), <code>'timeformat_string'</code>, <code>'epochsecs'</code>, or\n            <code>'epochmillisecs'</code>. It defaults to 10. Using <code>auto</code> recognizes\n         most strings, even some that aren't supported when you use a time format string. </p>\n         <p>If your date and time values use formats different from each other, set this parameter\n         to <code>auto</code>. </p>"}))
    RedshiftSettings.add_member(:trim_blanks, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'TrimBlanks', traits: {"smithy.api#documentation" => "<p>A value that specifies to remove the trailing white space characters from a VARCHAR\n         string. This parameter applies only to columns with a VARCHAR data type. Choose\n            <code>true</code> to remove unneeded white space. The default is\n         <code>false</code>.</p>"}))
    RedshiftSettings.add_member(:truncate_columns, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'TruncateColumns', traits: {"smithy.api#documentation" => "<p>A value that specifies to truncate data in columns to the appropriate number of\n         characters, so that the data fits in the column. This parameter applies only to columns\n         with a VARCHAR or CHAR data type, and rows with a size of 4 MB or less. Choose\n            <code>true</code> to truncate data. The default is <code>false</code>.</p>"}))
    RedshiftSettings.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>An Amazon Redshift user name for a registered user.</p>"}))
    RedshiftSettings.add_member(:write_buffer_size, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'WriteBufferSize', traits: {"smithy.api#documentation" => "<p>The size (in KB) of the in-memory file write buffer used when generating .csv files on\n         the local disk at the DMS replication instance. The default value is 1000 (buffer size is\n         1000KB).</p>"}))
    RedshiftSettings.add_member(:secrets_manager_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The full Amazon Resource Name (ARN) of the IAM role that specifies DMS as the trusted\n         entity and grants the required permissions to access the value in\n            <code>SecretsManagerSecret</code>. The role must allow the <code>iam:PassRole</code>\n         action. <code>SecretsManagerSecret</code> has the value of the Amazon Web Services Secrets Manager secret that\n         allows access to the Amazon Redshift endpoint.</p>\n         <note>\n            <p>You can specify one of two sets of values for these permissions. You can specify the\n            values for this setting and <code>SecretsManagerSecretId</code>. Or you can specify\n            clear-text values for <code>UserName</code>, <code>Password</code>,\n               <code>ServerName</code>, and <code>Port</code>. You can't specify both. For more\n            information on creating this <code>SecretsManagerSecret</code> and the\n               <code>SecretsManagerAccessRoleArn</code> and <code>SecretsManagerSecretId</code>\n            required to access it, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Security.html#security-iam-secretsmanager\">Using secrets to access Database Migration Service resources</a> in the\n               <i>Database Migration Service User Guide</i>.</p>\n         </note>"}))
    RedshiftSettings.add_member(:secrets_manager_secret_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecretsManagerSecretId', traits: {"smithy.api#documentation" => "<p>The full ARN, partial ARN, or friendly name of the <code>SecretsManagerSecret</code>\n         that contains the Amazon Redshift endpoint connection details.</p>"}))
    RedshiftSettings.add_member(:map_boolean_as_boolean, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MapBooleanAsBoolean', traits: {"smithy.api#documentation" => "<p>When true, lets Redshift migrate the boolean type as boolean. By default, Redshift\n         migrates booleans as <code>varchar(1)</code>. You must set this setting on both the source\n         and target endpoints for it to take effect.</p>"}))
