    ReplicationTask.add_member(:replication_task_stats, Smithy::Schema::Shapes::ShapeRef.new(shape: ReplicationTaskStats, location_name: 'ReplicationTaskStats', traits: {"smithy.api#documentation" => "<p>The statistics for the task, including elapsed time, tables loaded, and table\n         errors.</p>"}))
    ReplicationTask.add_member(:task_data, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TaskData', traits: {"smithy.api#documentation" => "<p>Supplemental information that the task requires to migrate the data for certain source\n         and target endpoints. For more information, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Tasks.TaskData.html\">Specifying Supplemental Data for\n            Task Settings</a> in the <i>Database Migration Service User Guide.</i>\n         </p>"}))
