    ReplicationTaskIndividualAssessment.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>Individual assessment status.</p>\n         <p>This status can have one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>\"cancelled\"</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>\"error\"</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>\"failed\"</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>\"passed\"</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>\"pending\"</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>\"skipped\"</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>\"running\"</code>\n               </p>\n            </li>\n         </ul>"}))
