    ReplicationTaskStats.add_member(:full_load_progress_percent, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'FullLoadProgressPercent', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The percent complete for the full load migration task.</p>"}))
    ReplicationTaskStats.add_member(:elapsed_time_millis, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'ElapsedTimeMillis', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The elapsed time of the task, in milliseconds.</p>"}))
    ReplicationTaskStats.add_member(:tables_loaded, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'TablesLoaded', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of tables loaded for this task.</p>"}))
    ReplicationTaskStats.add_member(:tables_loading, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'TablesLoading', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of tables currently loading for this task.</p>"}))
    ReplicationTaskStats.add_member(:tables_queued, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'TablesQueued', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of tables queued for this task.</p>"}))
    ReplicationTaskStats.add_member(:tables_errored, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'TablesErrored', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of errors that have occurred during this task.</p>"}))
    ReplicationTaskStats.add_member(:fresh_start_date, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'FreshStartDate', traits: {"smithy.api#documentation" => "<p>The date the replication task was started either with a fresh start or a target\n         reload.</p>"}))
    ReplicationTaskStats.add_member(:start_date, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'StartDate', traits: {"smithy.api#documentation" => "<p>The date the replication task was started either with a fresh start or a resume. For\n         more information, see <a href=\"https://docs.aws.amazon.com/dms/latest/APIReference/API_StartReplicationTask.html#DMS-StartReplicationTask-request-StartReplicationTaskType\">StartReplicationTaskType</a>.</p>"}))
    ReplicationTaskStats.add_member(:stop_date, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'StopDate', traits: {"smithy.api#documentation" => "<p>The date the replication task was stopped.</p>"}))
    ReplicationTaskStats.add_member(:full_load_start_date, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'FullLoadStartDate', traits: {"smithy.api#documentation" => "<p>The date the replication task full load was started.</p>"}))
    ReplicationTaskStats.add_member(:full_load_finish_date, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'FullLoadFinishDate', traits: {"smithy.api#documentation" => "<p>The date the replication task full load was completed.</p>"}))
    ReplicationTaskStats.type = Types::ReplicationTaskStats
