    ResourceAlreadyExistsFault.add_member(:resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'resourceArn', traits: {"smithy.api#documentation" => "<p></p>"}))
    ResourceAlreadyExistsFault.type = Types::ResourceAlreadyExistsFault
