    ResourcePendingMaintenanceActions.add_member(:resource_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResourceIdentifier', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the DMS resource that the pending maintenance action\n         applies to. For information about creating an ARN, see <a href=\"https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Introduction.AWS.ARN.html\"> Constructing an Amazon\n            Resource Name (ARN) for DMS</a> in the DMS documentation.</p>"}))
    ResourcePendingMaintenanceActions.add_member(:pending_maintenance_action_details, Smithy::Schema::Shapes::ShapeRef.new(shape: PendingMaintenanceActionDetails, location_name: 'PendingMaintenanceActionDetails', traits: {"smithy.api#documentation" => "<p>Detailed information about the pending maintenance action.</p>"}))
    ResourcePendingMaintenanceActions.type = Types::ResourcePendingMaintenanceActions
