    ResourceQuotaExceededFault.type = Types::ResourceQuotaExceededFault
    RunFleetAdvisorLsaAnalysisResponse.add_member(:lsa_analysis_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LsaAnalysisId', traits: {"smithy.api#documentation" => "<p>The ID of the LSA analysis run.</p>"}))
    RunFleetAdvisorLsaAnalysisResponse.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the LSA analysis, for example <code>COMPLETED</code>.</p>"}))
    RunFleetAdvisorLsaAnalysisResponse.type = Types::RunFleetAdvisorLsaAnalysisResponse
