    StartReplicationTaskAssessmentRunMessage.add_member(:service_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServiceAccessRoleArn', traits: {"smithy.api#documentation" => "<p>ARN of the service role needed to start the assessment run. The role must allow the\n            <code>iam:PassRole</code> action.</p>", "smithy.api#required" => {}}))
    StartReplicationTaskAssessmentRunMessage.add_member(:result_location_bucket, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResultLocationBucket', traits: {"smithy.api#documentation" => "<p>Amazon S3 bucket where you want DMS to store the results of this assessment\n         run.</p>", "smithy.api#required" => {}}))
    StartReplicationTaskAssessmentRunMessage.add_member(:result_location_folder, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResultLocationFolder', traits: {"smithy.api#documentation" => "<p>Folder within an Amazon S3 bucket where you want DMS to store the results of this\n         assessment run.</p>"}))
    StartReplicationTaskAssessmentRunMessage.add_member(:result_encryption_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResultEncryptionMode', traits: {"smithy.api#documentation" => "<p>Encryption mode that you can specify to encrypt the results of this assessment run. If\n         you don't specify this request parameter, DMS stores the assessment run results\n         without encryption. You can specify one of the options following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>\"SSE_S3\"</code> – The server-side encryption provided as a default by\n               Amazon S3.</p>\n            </li>\n            <li>\n               <p>\n                  <code>\"SSE_KMS\"</code> – Key Management Service (KMS) encryption. This encryption can\n               use either a custom KMS encryption key that you specify or the default KMS encryption\n               key that DMS provides.</p>\n            </li>\n         </ul>"}))
    StartReplicationTaskAssessmentRunMessage.add_member(:result_kms_key_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResultKmsKeyArn', traits: {"smithy.api#documentation" => "<p>ARN of a custom KMS encryption key that you specify when you set\n            <code>ResultEncryptionMode</code> to <code>\"SSE_KMS</code>\".</p>"}))
    StartReplicationTaskAssessmentRunMessage.add_member(:assessment_run_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AssessmentRunName', traits: {"smithy.api#documentation" => "<p>Unique name to identify the assessment run.</p>", "smithy.api#required" => {}}))
    StartReplicationTaskAssessmentRunMessage.add_member(:include_only, Smithy::Schema::Shapes::ShapeRef.new(shape: IncludeTestList, location_name: 'IncludeOnly', traits: {"smithy.api#documentation" => "<p>Space-separated list of names for specific individual assessments that you want to\n         include. These names come from the default list of individual assessments that DMS\n         supports for the associated migration task. This task is specified by\n            <code>ReplicationTaskArn</code>.</p>\n         <note>\n            <p>You can't set a value for <code>IncludeOnly</code> if you also set a value for\n               <code>Exclude</code> in the API operation.\n            </p>\n            <p>To identify the names of the default individual assessments that DMS supports for\n            the associated migration task, run the\n               <code>DescribeApplicableIndividualAssessments</code> operation using its own\n               <code>ReplicationTaskArn</code> request parameter.</p>\n         </note>"}))
    StartReplicationTaskAssessmentRunMessage.add_member(:exclude, Smithy::Schema::Shapes::ShapeRef.new(shape: ExcludeTestList, location_name: 'Exclude', traits: {"smithy.api#documentation" => "<p>Space-separated list of names for specific individual assessments that you want to\n         exclude. These names come from the default list of individual assessments that DMS\n         supports for the associated migration task. This task is specified by\n            <code>ReplicationTaskArn</code>.</p>\n         <note>\n            <p>You can't set a value for <code>Exclude</code> if you also set a value for\n               <code>IncludeOnly</code> in the API operation.</p>\n            <p>To identify the names of the default individual assessments that DMS supports for\n            the associated migration task, run the\n               <code>DescribeApplicableIndividualAssessments</code> operation using its own\n               <code>ReplicationTaskArn</code> request parameter.</p>\n         </note>"}))
