    TimestreamSettings.add_member(:memory_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MemoryDuration', traits: {"smithy.api#documentation" => "<p>Set this attribute to specify the length of time to store all of the tables in memory\n         that are migrated into Amazon Timestream from the source database. Time is measured in\n         units of hours. When Timestream data comes in, it first resides in memory for the specified\n         duration, which allows quick access to it.</p>", "smithy.api#required" => {}}))
    TimestreamSettings.add_member(:magnetic_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MagneticDuration', traits: {"smithy.api#documentation" => "<p>Set this attribute to specify the default magnetic duration applied to the Amazon\n         Timestream tables in days. This is the number of days that records remain in magnetic store\n         before being discarded. For more information, see <a href=\"https://docs.aws.amazon.com/timestream/latest/developerguide/storage.html\">Storage</a> in the <a href=\"https://docs.aws.amazon.com/timestream/latest/developerguide/\">Amazon Timestream Developer\n            Guide</a>.</p>", "smithy.api#required" => {}}))
    TimestreamSettings.add_member(:cdc_inserts_and_updates, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CdcInsertsAndUpdates', traits: {"smithy.api#documentation" => "<p>Set this attribute to <code>true</code> to specify that DMS only applies inserts and\n         updates, and not deletes. Amazon Timestream does not allow deleting records, so if this\n         value is <code>false</code>, DMS nulls out the corresponding record in the Timestream\n         database rather than deleting it.</p>"}))
    TimestreamSettings.add_member(:enable_magnetic_store_writes, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableMagneticStoreWrites', traits: {"smithy.api#documentation" => "<p>Set this attribute to <code>true</code> to enable memory store writes. When this value\n         is <code>false</code>, DMS does not write records that are older in days than the value\n         specified in <code>MagneticDuration</code>, because Amazon Timestream does not allow memory\n         writes by default. For more information, see <a href=\"https://docs.aws.amazon.com/timestream/latest/developerguide/storage.html\">Storage</a> in the <a href=\"https://docs.aws.amazon.com/timestream/latest/developerguide/\">Amazon Timestream Developer\n            Guide</a>.</p>"}))
